                    )],
                ));
            }
        }
    }
}


fn check_multilingual(catalogue: &Catalogue, required: &[String], report: &mut CheckReport) {
    let mut named: Vec<(String, String, &crate::Names)> = Vec::new();
    named.push(("catalogue".into(), "catalogue.metadata.names".into(), &catalogue.metadata.names));
    named.push((catalogue.manufacturer.id.clone(), "catalogue.manufacturer.names".into(), &catalogue.manufacturer.names));
    for (_i, g) in catalogue.product_groups.iter().enumerate() {
        named.push((g.id.clone(), format!("catalogue.productGroups[id={}].names", g.id), &g.names));
    }
    for (_i, c) in catalogue.product_classes.iter().enumerate() {
        named.push((c.id.clone(), format!("catalogue.productClasses[id={}].names", c.id), &c.names));
    }
    for (_i, s) in catalogue.product_series.iter().enumerate() {
        named.push((s.id.clone(), format!("catalogue.productSeries[id={}].names", s.id), &s.names));
    }
    for (_i, p) in catalogue.products.iter().enumerate() {
        named.push((p.id.clone(), format!("catalogue.products[id={}].names", p.id), &p.names));
    }
    for (_i, d) in catalogue.property_definitions.iter().enumerate() {
        named.push((d.id.clone(), format!("catalogue.propertyDefinitions[id={}].names", d.id), &d.names));
    }

    let mut missing_count = 0u32;
    for (id, path, names) in named {
        let missing = names_cover(names, required);
        if missing.is_empty() {
            continue;
        }
        missing_count += 1;
        for locale in missing {
            report.push(fail(
                format!("iso16757.1.5.1.name.{id}.{locale}"),
                "1",
                "5.1",
                subject(&id, path.clone(), names.preferred.text.clone(), names.preferred.text.clone()),
                copy("Multilingual name coverage", "Mehrsprachige Namensabdeckung"),
                copy(
                    format!("Entity '{id}' lacks a name in required language '{locale}' (catalogue declares: {}).", required.join(", ")),
                    format!("Entität '{id}' hat keinen Namen in der geforderten Sprache '{locale}' (Katalog fordert: {}).", required.join(", ")),
                ),
                {
                    let mut remedies = Vec::new();
                    if !names.alternatives.is_empty() {
                        remedies.push(Remedy::one_of(
                            subject(&id, format!("{path}.alternatives[0].locale"), names.preferred.text.clone(), names.preferred.text.clone()),
                            vec![locale.clone()],
                            copy(
                                format!("Set alternatives[0].locale to '{locale}' so '{id}' covers the required language."),
                                format!("alternatives[0].locale auf '{locale}' setzen, damit '{id}' die geforderte Sprache abdeckt."),
                            ),
                        ));
                        remedies.push(Remedy::one_of(
                            subject(&id, format!("{path}.alternatives[0].text"), names.preferred.text.clone(), names.preferred.text.clone()),
                            vec![names.preferred.text.clone()],
                            copy(
                                format!("Keep alternatives[0].text as a non-empty name for '{id}' in language '{locale}'."),
                                format!("alternatives[0].text als nicht-leeren Namen für '{id}' in Sprache '{locale}' belassen."),
                            ),
                        ));
                    }
                    remedies.push(Remedy::one_of(
                        subject(&id, format!("{path}.preferred.locale"), names.preferred.text.clone(), names.preferred.text.clone()),
                        vec![locale.clone()],
                        copy(
                            format!("Or set preferred.locale to '{locale}' if that name should be the primary language for '{id}'."),
                            format!("Oder preferred.locale auf '{locale}' setzen, wenn dieser Name die Primärsprache für '{id}' sein soll."),
                        ),
                    ));
                    remedies
                },
            ));
        }
    }
    if missing_count == 0 {
        report.push(pass(
            "iso16757.1.5.1.names",
            "1",
            "5.1",
            catalogue_subject(),
            copy("Multilingual name coverage", "Mehrsprachige Namensabdeckung"),
            copy(
                format!("All named catalogue entities cover required languages ({}).", required.join(", ")),
                format!("Alle benannten Katalogentitäten decken die geforderten Sprachen ab ({}).", required.join(", ")),
            ),
        ));
    }
}

fn product_class<'a>(catalogue: &'a Catalogue, product: &Product) -> Option<&'a crate::part_1::ProductClass> {
    let series = catalogue.product_series.iter().find(|s| s.id == product.series_id)?;
    catalogue.product_classes.iter().find(|c| c.id == series.class_id)
}

fn check_required_properties(catalogue: &Catalogue, report: &mut CheckReport) {
    let mut checked = 0u32;
    let mut failed = 0u32;
    for (_pi, product) in catalogue.products.iter().enumerate() {
        let Some(class) = product_class(catalogue, product) else {
            continue;
        };
        for req in &class.required_property_ids {
            checked += 1;
            let on_product = product.static_properties.iter().any(|pv| &pv.definition_id == req);
            let missing_variants: Vec<&str> = product
                .variants
                .iter()
                .filter(|v| !on_product && v.property_values.iter().all(|pv| &pv.definition_id != req))
                .map(|v| v.id.as_str())
                .collect();
            if !on_product && (product.variants.is_empty() || !missing_variants.is_empty()) {
                failed += 1;
                let variant_hint = if missing_variants.is_empty() {
                    "product.staticProperties".to_string()
                } else {
                    format!("variants {}", missing_variants.join(", "))
                };
                report.push(fail(
                    format!("iso16757.1.5.2.required.{}.{}", product.id, req),
                    "1",
                    "5.2",
                    subject(&product.id, format!("catalogue.products[id={}].staticProperties", product.id), &product.names.preferred.text, &product.names.preferred.text),
                    copy("Required class property", "Erforderliche Klasseneigenschaft"),
                    copy(
                        format!("Product '{}' (class '{}') is missing required property '{}'.", product.id, class.id, req),
                        format!("Produkt '{}' (Klasse '{}') fehlt die erforderliche Eigenschaft '{}'.", product.id, class.id, req),
                    ),
                    vec![Remedy {
                        target: subject(&product.id, format!("catalogue.products[id={}].staticProperties", product.id), &product.names.preferred.text, &product.names.preferred.text),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::Exactly,
                        options: vec![req.clone()],
                        action: copy(
                            format!("Add property value for '{req}' on {variant_hint}."),
                            format!("Eigenschaftswert für '{req}' auf {variant_hint} ergänzen."),
                        ),
                        applicable: false,
                    }],
                ));
            }
        }
    }
    if checked == 0 {
        report.push(na(
            "iso16757.1.5.2.required",
            "1",
            "5.2",
            catalogue_subject(),
            copy("Required class property", "Erforderliche Klasseneigenschaft"),
            copy("No products with class-required properties to check.", "Keine Produkte mit klassenpflichtigen Eigenschaften zu prüfen."),
        ));
    } else if failed == 0 {
        report.push(pass(
            "iso16757.1.5.2.required",
            "1",
            "5.2",
            catalogue_subject(),
            copy("Required class property", "Erforderliche Klasseneigenschaft"),
            copy(
                format!("All {checked} required class property bindings are present."),
                format!("Alle {checked} erforderlichen Klasseneigenschaftsbindungen sind vorhanden."),
            ),
        ));
    }
}

fn check_property_values(catalogue: &Catalogue, dictionary: &crate::part_4::Dictionary, report: &mut CheckReport) {
    let mut checked = 0u32;
    let mut failed = 0u32;
    for (_pi, product) in catalogue.products.iter().enumerate() {
        let mut values: Vec<(String, &CatalogueValue, String)> = Vec::new();
        for pv in &product.static_properties {
            values.push((pv.definition_id.clone(), &pv.value, format!("product:{}", product.id)));
        }
        for v in &product.variants {
            for pv in &v.property_values {
                values.push((pv.definition_id.clone(), &pv.value, format!("variant:{}", v.id)));
            }
        }
        for (def_id, value, scope) in values {
            checked += 1;
            let Some(def) = def_by_id(catalogue, &def_id) else {
                failed += 1;
                report.push(fail(
                    format!("iso16757.1.5.3.unknownDef.{}.{}", scope, def_id),
                    "1",
                    "5.3",
                    subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                    copy("Property definition resolvable", "Eigenschaftsdefinition auflösbar"),
                    copy(
                        format!("Property value on {scope} references unknown definition '{def_id}'."),
                        format!("Eigenschaftswert auf {scope} verweist auf unbekannte Definition '{def_id}'."),
                    ),
                    vec![Remedy::one_of(
                        subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                        catalogue.property_definitions.iter().map(|d| d.id.clone()).collect(),
                        copy(
                            format!("Point definitionId at an existing property definition or create '{def_id}'."),
                            format!("definitionId auf eine vorhandene Definition setzen oder '{def_id}' anlegen."),
                        ),
                    )],
                ));
                continue;
            };

            if !quantity_dimension_ok(value, def) {
                failed += 1;
                report.push(fail(
                    format!("iso16757.1.5.3.unit.{}.{}", scope, def_id),
                    "1",
                    "5.3",
                    subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                    copy("Property unit / dimension", "Eigenschaftseinheit / Dimension"),
                    copy(
                        format!("Value of '{def_id}' on {scope} does not match the definition unit/dimension."),
                        format!("Wert von '{def_id}' auf {scope} entspricht nicht der Definitions-Einheit/Dimension."),
                    ),
                    vec![Remedy {
                        target: subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::Exactly,
                        options: def.unit.as_ref().map(|u| u.symbol.clone()).into_iter().collect(),
                        action: copy(
                            format!("Provide a quantity in the definition unit for '{def_id}' (symbol {:?}).", def.unit.as_ref().map(|u| u.symbol.as_str())),
                            format!("Größe in der Definitionseinheit für '{def_id}' angeben (Symbol {:?}).", def.unit.as_ref().map(|u| u.symbol.as_str())),
                        ),
                        applicable: true,
                    }],
                ));
            }

            if let Some(dict_prop_id) = &def.dictionary_property_id {
                if let Some(dict_prop) = crate::standards::v1::subsets::any::schema::part_4::resolve_property(dictionary, dict_prop_id) {
                    for constraint in &dict_prop.value_constraints {
                            if let Some(v) = value_as_f64(value) {
                                if let Some(min) = constraint.min {
                                    if v < min {
                                        failed += 1;
                                        report.push(assess(
                                            format!("iso16757.1.5.3.min.{scope}.{def_id}"),
                                            "1",
                                            "5.3",
                                            subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                                            copy("Property value minimum", "Eigenschaftswert-Minimum"),
                                            copy(
                                                format!("Value {v} of '{def_id}' on {scope} is below minimum {min}."),
                                                format!("Wert {v} von '{def_id}' auf {scope} liegt unter Minimum {min}."),
                                            ),
                                            CheckStatus::Fail,
                                            Quantity::new(QuantityKind::Dimensionless, v),
                                            Quantity::new(QuantityKind::Dimensionless, min),
                                            vec![Remedy::at_least(
                                                subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                                                Quantity::new(QuantityKind::Dimensionless, v),
                                                Quantity::new(QuantityKind::Dimensionless, min),
                                                copy(
                                                    format!("Increase '{def_id}' on {scope} from {v} to at least {min}."),
                                                    format!("'{def_id}' auf {scope} von {v} auf mindestens {min} erhöhen."),
                                                ),
                                            )],
                                        ));
                                    }
                                }
                                if let Some(max) = constraint.max {
                                    if v > max {
                                        failed += 1;
                                        report.push(assess(
                                            format!("iso16757.1.5.3.max.{scope}.{def_id}"),
                                            "1",
                                            "5.3",
                                            subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                                            copy("Property value maximum", "Eigenschaftswert-Maximum"),
                                            copy(
                                                format!("Value {v} of '{def_id}' on {scope} exceeds maximum {max}."),
                                                format!("Wert {v} von '{def_id}' auf {scope} überschreitet Maximum {max}."),
                                            ),
                                            CheckStatus::Fail,
                                            Quantity::new(QuantityKind::Dimensionless, v),
                                            Quantity::new(QuantityKind::Dimensionless, max),
                                            vec![Remedy::at_most(
                                                subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                                                Quantity::new(QuantityKind::Dimensionless, v),
                                                Quantity::new(QuantityKind::Dimensionless, max),
                                                copy(
                                                    format!("Reduce '{def_id}' on {scope} from {v} to at most {max}."),
                                                    format!("'{def_id}' auf {scope} von {v} auf höchstens {max} verringern."),
                                                ),
                                            )],
                                        ));
                                    }
                                }
                                if !constraint.allowed_values.is_empty() {
                                    let as_text = match value {
                                        CatalogueValue::Decimal { value } => value.to_string(),
                                        CatalogueValue::Integer { value } => value.to_string(),
                                        CatalogueValue::Text { value } | CatalogueValue::Enumeration { value } | CatalogueValue::Identifier { value } => value.clone(),
                                        _ => String::new(),
                                    };
                                    if !as_text.is_empty() && !constraint.allowed_values.iter().any(|a| a == &as_text) {
                                        failed += 1;
                                        report.push(fail(
                                            format!("iso16757.1.5.3.enum.{scope}.{def_id}"),
                                            "1",
                                            "5.3",
                                            subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                                            copy("Property allowed values", "Zulässige Eigenschaftswerte"),
                                            copy(
                                                format!("Value '{as_text}' of '{def_id}' on {scope} is not in {:?}.", constraint.allowed_values),
                                                format!("Wert '{as_text}' von '{def_id}' auf {scope} ist nicht in {:?}.", constraint.allowed_values),
                                            ),
                                            vec![Remedy::one_of(
                                                subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                                                constraint.allowed_values.clone(),
                                                copy(
                                                    format!("Set '{def_id}' on {scope} to one of {:?}.", constraint.allowed_values),
                                                    format!("'{def_id}' auf {scope} auf einen der Werte {:?} setzen.", constraint.allowed_values),
                                                ),
                                            )],
                                        ));
                                    }
                                }
                            }
                    }
                }
            }
        }
    }

    if checked == 0 {
        report.push(na(
            "iso16757.1.5.3.values",
            "1",
            "5.3",
            catalogue_subject(),
            copy("Property value conformance", "Eigenschaftswert-Konformität"),
            copy("No product property values to validate.", "Keine Produkteigenschaftswerte zu prüfen."),
        ));
    } else if failed == 0 {
        report.push(pass(
            "iso16757.1.5.3.values",
            "1",
            "5.3",
            catalogue_subject(),
            copy("Property value conformance", "Eigenschaftswert-Konformität"),
            copy(
                format!("All {checked} property values match definitions and dictionary constraints."),
                format!("Alle {checked} Eigenschaftswerte entsprechen Definitionen und Wörterbuchbeschränkungen."),
            ),
        ));
    }
}

fn check_property_definition_units(catalogue: &Catalogue, dictionary: &crate::part_4::Dictionary, report: &mut CheckReport) {
    for def in &catalogue.property_definitions {
        let path = format!("catalogue.propertyDefinitions[id={}]", def.id);
        // dictionaryPropertyId resolvable — ISO 16757-1 §5.3 / Part 4 property dictionary binding
        if let Some(dict_prop_id) = &def.dictionary_property_id {
            let link_path = format!("{path}.dictionaryPropertyId");
            let resolved_idx = dictionary
                .properties
                .iter()
                .position(|p| p.id == *dict_prop_id)
                .map(|i| (i + 1) as f64);
            let resolved = resolved_idx.is_some();
            if resolved {
                let ordinal = resolved_idx.unwrap_or(1.0);
                report.push(assess(
                    format!("iso16757.1.5.3.dictProp.{}", def.id),
                    "1",
                    "5.3",
                    subject(&def.id, link_path, &def.names.preferred.text, &def.names.preferred.text),
                    copy("Dictionary property link", "Wörterbuch-Eigenschaftsverknüpfung"),
                    copy(
                        format!("Property definition '{}' links to dictionary property '{}' (slot {ordinal}).", def.id, dict_prop_id),
                        format!("Eigenschaftsdefinition '{}' verknüpft Wörterbucheigenschaft '{}' (Slot {ordinal}).", def.id, dict_prop_id),
                    ),
                    CheckStatus::Pass,
                    q_dim(ordinal),
                    q_dim(1.0),
                    Vec::new(),
                ));
            } else {
                report.push(assess(
                    format!("iso16757.1.5.3.dictProp.{}", def.id),
                    "1",
                    "5.3",
                    subject(&def.id, link_path.clone(), &def.names.preferred.text, &def.names.preferred.text),
                    copy("Dictionary property link", "Wörterbuch-Eigenschaftsverknüpfung"),
                    copy(
                        format!("Property definition '{}' links to missing dictionary property '{}'.", def.id, dict_prop_id),
                        format!("Eigenschaftsdefinition '{}' verweist auf fehlende Wörterbucheigenschaft '{}'.", def.id, dict_prop_id),
                    ),
                    CheckStatus::Fail,
                    q_dim(0.0),
                    q_dim(1.0),
                    vec![Remedy::one_of(
                        subject(&def.id, link_path, &def.names.preferred.text, &def.names.preferred.text),
                        dictionary.properties.iter().map(|p| p.id.clone()).collect(),
                        copy(
                            format!("Set dictionaryPropertyId to an existing dictionary property or create '{}'.", dict_prop_id),
                            format!("dictionaryPropertyId auf eine vorhandene Wörterbucheigenschaft setzen oder '{}' anlegen.", dict_prop_id),
                        ),
                    )],
                ));
            }
        }
        // dataType non-empty (Part 1 §6 / Part 4 property typing)
        if def.data_type.trim().is_empty() {
            report.push(fail(
                format!("iso16757.1.6.dataType.{}", def.id),
                "1",
                "6",
                subject(&def.id, format!("{path}.dataType"), &def.names.preferred.text, &def.names.preferred.text),
                copy("Property data type", "Eigenschafts-Datentyp"),
                copy(
                    format!("Property '{0}' dataType must be non-empty.", def.id),
                    format!("Eigenschaft '{0}' dataType darf nicht leer sein.", def.id),
                ),
                vec![Remedy::one_of(
                    subject(&def.id, format!("{path}.dataType"), &def.names.preferred.text, &def.names.preferred.text),
                    vec!["decimal".into(), "quantity".into(), "integer".into(), "text".into()],
                    copy("Set dataType to a Part 4 property data type.", "dataType auf einen Teil-4-Eigenschaftsdatentyp setzen."),
                )],
            ));
        } else {
            report.push(assess(
                format!("iso16757.1.6.dataType.{}", def.id),
                "1",
                "6",
                subject(&def.id, format!("{path}.dataType"), &def.names.preferred.text, &def.names.preferred.text),
                copy("Property data type", "Eigenschafts-Datentyp"),
                copy(
                    format!("Property '{}' dataType is '{}'.", def.id, def.data_type),
                    format!("Eigenschaft '{}' dataType ist '{}'.", def.id, def.data_type),
                ),
                CheckStatus::Pass,
                q_dim(controlled_ordinal(&def.data_type, &["decimal", "quantity", "integer", "text", "boolean", "controlled"])),
                q_dim(1.0),
                Vec::new(),
            ));
        }
        // cardinality min <= max (Part 1 §6)
        let max_v = def.cardinality.max.unwrap_or(u32::MAX) as f64;
        let min_v = def.cardinality.min as f64;
        if min_v > max_v {
            report.push(fail(
                format!("iso16757.1.6.cardinality.{}", def.id),
                "1",
                "6",
                subject(&def.id, format!("{path}.cardinality.min"), &def.names.preferred.text, &def.names.preferred.text),
                copy("Property cardinality", "Eigenschafts-Kardinalität"),
                copy(
                    format!("Property '{}' cardinality min ({}) exceeds max.", def.id, def.cardinality.min),
                    format!("Eigenschaft '{}' Kardinalität min ({}) überschreitet max.", def.id, def.cardinality.min),
                ),
                vec![Remedy {
                    target: subject(&def.id, format!("{path}.cardinality.min"), &def.names.preferred.text, &def.names.preferred.text),
                    current: q_dim(min_v),
                    required: q_dim(max_v.min(min_v)),
                    bound: RemedyBound::AtMost,
                    options: Vec::new(),
                    action: copy("Lower cardinality.min or raise cardinality.max.", "cardinality.min senken oder cardinality.max erhöhen."),
                    applicable: true,
                }],
            ));
        } else {
            report.push(assess(
                format!("iso16757.1.6.cardinality.{}", def.id),
                "1",
                "6",
                subject(&def.id, format!("{path}.cardinality.min"), &def.names.preferred.text, &def.names.preferred.text),
                copy("Property cardinality", "Eigenschafts-Kardinalität"),
                copy(
                    format!("Property '{}' cardinality [{min_v}, {max_v}] is ordered.", def.id),
                    format!("Eigenschaft '{}' Kardinalität [{min_v}, {max_v}] ist geordnet.", def.id),
                ),
                CheckStatus::Pass,
                q_dim(min_v),
                q_dim(if max_v.is_finite() && max_v < 1.0e9 { max_v } else { min_v }),
                Vec::new(),
            ));
        }
        if let Some(unit) = &def.unit {
            let dim_score = (unit.dimension.length.abs()
                + unit.dimension.mass.abs()
                + unit.dimension.time.abs()
                + unit.dimension.temperature.abs()) as f64;
            if unit.symbol.trim().is_empty() || unit.si_factor <= 0.0 {
                report.push(fail(
                    format!("iso16757.1.6.unit.{}", def.id),
                    "1",
                    "6",
                    subject(&def.id, format!("{path}.unit.symbol"), &def.names.preferred.text, &def.names.preferred.text),
                    copy("Property unit", "Eigenschafts-Einheit"),
                    copy(
                        format!("Property '{}' unit needs a symbol and positive siFactor (Part 1 §6 / Part 4).", def.id),
                        format!("Eigenschaft '{}' Einheit braucht Symbol und positiven siFactor (Teil 1 §6 / Teil 4).", def.id),
                    ),
                    vec![Remedy {
                        target: subject(&def.id, format!("{path}.unit.siFactor"), &def.names.preferred.text, &def.names.preferred.text),
                        current: q_dim(unit.si_factor),
                        required: q_dim(1.0),
                        bound: RemedyBound::Exactly,
                        options: Vec::new(),
                        action: copy("Set unit.symbol and a positive unit.siFactor.", "unit.symbol und positiven unit.siFactor setzen."),
                        applicable: true,
                    }],
                ));
            } else {
                report.push(assess(
                    format!("iso16757.1.6.unit.{}", def.id),
                    "1",
                    "6",
                    subject(&def.id, format!("{path}.unit.siFactor"), &def.names.preferred.text, &def.names.preferred.text),
                    copy("Property unit", "Eigenschafts-Einheit"),
                    copy(
                        format!("Property '{}' unit '{}' siFactor {} (dim score {dim_score}).", def.id, unit.symbol, unit.si_factor),
                        format!("Eigenschaft '{}' Einheit '{}' siFactor {} (Dim-Score {dim_score}).", def.id, unit.symbol, unit.si_factor),
                    ),
                    CheckStatus::Pass,
                    q_dim(unit.si_factor + dim_score * 1.0),
                    q_dim(unit.si_factor + dim_score * 1.0),
                    Vec::new(),
                ));
                // Also bind symbol length so symbol edits change computed via a dedicated check id
                report.push(assess(
                    format!("iso16757.1.6.unitSymbol.{}", def.id),
                    "1",
                    "6",
                    subject(&def.id, format!("{path}.unit.symbol"), &def.names.preferred.text, &def.names.preferred.text),
                    copy("Property unit symbol", "Eigenschafts-Einheitssymbol"),
                    copy(
                        format!("Property '{}' unit symbol is '{}'.", def.id, unit.symbol),
                        format!("Eigenschaft '{}' Einheitssymbol ist '{}'.", def.id, unit.symbol),
                    ),
                    CheckStatus::Pass,
                    q_dim(controlled_ordinal(&unit.symbol, &["m", "mm", "cm", "kg", "g", "s", "K", "Pa", "bar", "W", "m3", "l", "-"])),
                    q_dim(1.0),
                    Vec::new(),
                ));
                // Dimension components bind their editable leaves (Part 1 §6 / SI).
                for (axis, value, path_suffix) in [
                    ("length", unit.dimension.length as f64, "unit.dimension.length"),
                    ("mass", unit.dimension.mass as f64, "unit.dimension.mass"),
                    ("time", unit.dimension.time as f64, "unit.dimension.time"),
                    ("temperature", unit.dimension.temperature as f64, "unit.dimension.temperature"),
                ] {
                    report.push(assess(
                        format!("iso16757.1.6.unitDim.{}.{axis}", def.id),
                        "1",
                        "6",
                        subject(&def.id, format!("{path}.{path_suffix}"), &def.names.preferred.text, &def.names.preferred.text),
                        copy("Property unit dimension", "Eigenschafts-Einheitsdimension"),
                        copy(
                            format!("Property '{}' unit dimension.{axis} = {value}.", def.id),
                            format!("Eigenschaft '{}' Einheitsdimension.{axis} = {value}.", def.id),
                        ),
                        CheckStatus::Pass,
                        q_dim(value),
                        q_dim(value),
                        Vec::new(),
                    ));
                }
                report.push(assess(
                    format!("iso16757.1.6.unitSiFactor.{}", def.id),
                    "1",
                    "6",
                    subject(&def.id, format!("{path}.unit.siFactor"), &def.names.preferred.text, &def.names.preferred.text),
                    copy("Property SI factor", "Eigenschafts-SI-Faktor"),
                    copy(
                        format!("Property '{}' unit siFactor = {}.", def.id, unit.si_factor),
                        format!("Eigenschaft '{}' Einheit siFactor = {}.", def.id, unit.si_factor),
                    ),
                    CheckStatus::Pass,
                    q_dim(unit.si_factor),
                    q_dim(unit.si_factor),
                    Vec::new(),
                ));
                report.push(assess(
                    format!("iso16757.1.6.unitDim.{}", def.id),
                    "1",
                    "6",
                    subject(&def.id, format!("{path}.unit.dimension.length"), &def.names.preferred.text, &def.names.preferred.text),
                    copy("Property unit dimension", "Eigenschafts-Einheitsdimension"),
                    copy(
                        format!("Property '{}' dimension L={} M={} T={} Θ={}.", def.id, unit.dimension.length, unit.dimension.mass, unit.dimension.time, unit.dimension.temperature),
                        format!("Eigenschaft '{}' Dimension L={} M={} T={} Θ={}.", def.id, unit.dimension.length, unit.dimension.mass, unit.dimension.time, unit.dimension.temperature),
                    ),
                    CheckStatus::Pass,
                    q_dim(
                        unit.dimension.length as f64 * 1000.0
                            + unit.dimension.mass as f64 * 100.0
                            + unit.dimension.time as f64 * 10.0
                            + unit.dimension.temperature as f64,
                    ),
                    q_dim(
                        unit.dimension.length as f64 * 1000.0
                            + unit.dimension.mass as f64 * 100.0
                            + unit.dimension.time as f64 * 10.0
                            + unit.dimension.temperature as f64,
                    ),
                    Vec::new(),
                ));
            }
        }
    }
}


fn check_variant_domains(catalogue: &Catalogue, report: &mut CheckReport) {
    let mut checked = 0u32;
    let mut failed = 0u32;
    for (_pi, product) in catalogue.products.iter().enumerate() {
        for (_vi, variant) in product.variants.iter().enumerate() {
            for (param_id, value) in &variant.parameter_values {
                checked += 1;
                if let Some(domain) = product.parameter_domains.iter().find(|d| &d.parameter_id == param_id) {
                    let pv = match value {
                        CatalogueValue::Decimal { value } | CatalogueValue::Quantity { value, .. } => *value,
                        CatalogueValue::Integer { value } => *value as f64,
                        _ => 0.0,
                    };
                    if !domain.allowed_values.is_empty() && !domain.allowed_values.contains(value) {
                        failed += 1;
                        let options: Vec<String> = domain.allowed_values.iter().filter_map(|v| match v {
                            CatalogueValue::Decimal { value } => Some(value.to_string()),
                            CatalogueValue::Integer { value } => Some(value.to_string()),
                            CatalogueValue::Text { value } | CatalogueValue::Enumeration { value } => Some(value.clone()),
                            _ => None,
                        }).collect();
                        report.push(assess(
                            format!("iso16757.1.6.1.domain.{}.{}.{}", product.id, variant.id, param_id),
                            "1",
                            "6.1",
                            subject(&variant.id, format!("catalogue.products[id={}].variants[id={}].parameterValues.{param_id}", product.id, variant.id), &variant.id, &variant.id),
                            copy("Variant parameter domain", "Varianten-Parameterbereich"),
                            copy(
                                format!("Variant '{}' parameter '{param_id}' = {pv} is outside the allowed domain.", variant.id),
                                format!("Variante '{}' Parameter '{param_id}' = {pv} liegt außerhalb des zulässigen Bereichs.", variant.id),
                            ),
                            CheckStatus::Fail,
                            q_dim(pv),
                            q_dim(1.0),
                            vec![Remedy::one_of(
                                subject(&variant.id, format!("catalogue.products[id={}].variants[id={}].parameterValues.{param_id}", product.id, variant.id), &variant.id, &variant.id),
                                options,
                                copy(
                                    format!("Set parameter '{param_id}' on variant '{}' to an allowed domain value.", variant.id),
                                    format!("Parameter '{param_id}' der Variante '{}' auf einen zulässigen Bereichswert setzen.", variant.id),
                                ),
                            )],
                        ));
                    } else {
                        report.push(assess(
                            format!("iso16757.1.6.1.domain.{}.{}.{}", product.id, variant.id, param_id),
                            "1",
                            "6.1",
                            subject(&variant.id, format!("catalogue.products[id={}].variants[id={}].parameterValues.{param_id}", product.id, variant.id), &variant.id, &variant.id),
                            copy("Variant parameter domain", "Varianten-Parameterbereich"),
                            copy(
                                format!("Variant '{}' parameter '{param_id}' = {pv} is inside the allowed domain.", variant.id),
                                format!("Variante '{}' Parameter '{param_id}' = {pv} liegt im zulässigen Bereich.", variant.id),
                            ),
                            CheckStatus::Pass,
                            q_dim(pv),
                            q_dim(pv),
                            Vec::new(),
                        ));
                    }
                }
            }
        }
    }
    if checked == 0 {
        report.push(na(
            "iso16757.1.6.1.domain",
            "1",
            "6.1",
            catalogue_subject(),
            copy("Variant parameter domain", "Varianten-Parameterbereich"),
            copy("No variant parameters to validate.", "Keine Variantenparameter zu prüfen."),
        ));
    } else if failed == 0 {
        report.push(pass(
            "iso16757.1.6.1.domain",
            "1",
            "6.1",
            catalogue_subject(),
            copy("Variant parameter domain", "Varianten-Parameterbereich"),
            copy(
                format!("All {checked} variant parameters lie inside their domains."),
                format!("Alle {checked} Variantenparameter liegen in ihren Bereichen."),
            ),
        ));
    }
}

fn check_variant_article_and_geometry(catalogue: &Catalogue, geometry: &crate::part_2::GeometryCatalogue, report: &mut CheckReport) {
    let geom_ids: HashSet<_> = geometry.objects.keys().cloned().collect();
    for product in &catalogue.products {
        for variant in &product.variants {
            if let Some(article) = &variant.article_number {
                let dn_token = variant
                    .parameter_values
                    .get("dn")
                    .map(|v| match v {
                        CatalogueValue::Decimal { value } | CatalogueValue::Quantity { value, .. } => {
                            format!("{}", *value as i64)
                        }
                        CatalogueValue::Integer { value } => format!("{value}"),
                        CatalogueValue::Text { value }
                        | CatalogueValue::Identifier { value }
                        | CatalogueValue::Enumeration { value } => value.clone(),
                        _ => String::new(),
                    })
                    .filter(|s| !s.is_empty());
                let expected_article = dn_token
                    .as_ref()
                    .map(|dn| format!("CV-{dn}"))
                    .unwrap_or_else(|| article.clone());
                let article_score = if article.trim().is_empty() {
                    0.0
                } else {
                    reference_slot_score(article, std::iter::once(expected_article.as_str()))
                };
                report.push(assess(
                    format!("iso16757.1.6.article.{}.{}", product.id, variant.id),
                    "1",
                    "6",
                    subject(&variant.id, format!("catalogue.products[id={}].variants[id={}].articleNumber", product.id, variant.id), &variant.id, &variant.id),
                    copy("Variant article number", "Varianten-Artikelnummer"),
                    copy(
                        format!("Variant '{}' articleNumber is '{article}'.", variant.id),
                        format!("Variante '{}' articleNumber ist '{article}'.", variant.id),
                    ),
                    if article.trim().is_empty() { CheckStatus::Fail } else { CheckStatus::Pass },
                    q_dim(article_score),
                    q_dim(1.0),
                    if article.trim().is_empty() {
                        vec![Remedy {
                            target: subject(&variant.id, format!("catalogue.products[id={}].variants[id={}].articleNumber", product.id, variant.id), &variant.id, &variant.id),
                            current: q_dim(0.0),
                            required: q_dim(1.0),
                            bound: RemedyBound::Exactly,
                            options: if expected_article.is_empty() {
                                Vec::new()
                            } else {
                                vec![expected_article.clone()]
                            },
                            action: copy("Set a non-empty articleNumber for the variant.", "Nicht-leere articleNumber für die Variante setzen."),
                            applicable: true,
                        }]
                    } else {
                        Vec::new()
                    },
                ));
            }
            if let Some(gid) = &variant.geometry_id {
                let ok = geom_ids.contains(gid);
                report.push(assess(
                    format!("iso16757.1.6.variantGeom.{}.{}", product.id, variant.id),
                    "1",
                    "6",
                    subject(&variant.id, format!("catalogue.products[id={}].variants[id={}].geometryId", product.id, variant.id), &variant.id, &variant.id),
                    copy("Variant geometry reference", "Varianten-Geometriereferenz"),
                    copy(
                        format!("Variant '{}' geometryId '{}' {}.", variant.id, gid, if ok { "resolves" } else { "is unknown" }),
                        format!("Variante '{}' geometryId '{}' {}.", variant.id, gid, if ok { "löst auf" } else { "ist unbekannt" }),
                    ),
                    if ok { CheckStatus::Pass } else { CheckStatus::Fail },
                    q_dim(reference_slot_score(gid, geom_ids.iter())),
                    q_dim(1.0),
                    if ok {
                        Vec::new()
                    } else {
                        vec![Remedy::one_of(
                            subject(&variant.id, format!("catalogue.products[id={}].variants[id={}].geometryId", product.id, variant.id), &variant.id, &variant.id),
                            geom_ids.iter().cloned().collect(),
                            copy("Point geometryId at an existing geometry object.", "geometryId auf vorhandenes Geometrieobjekt setzen."),
                        )]
                    },
                ));
            }
        }
        for (di, domain) in product.parameter_domains.iter().enumerate() {
            report.push(assess(
                format!("iso16757.1.6.paramId.{}.{}", product.id, domain.parameter_id),
                "1",
                "6",
                subject(&product.id, format!("catalogue.products[id={}].parameterDomains[{di}].parameterId", product.id), &product.names.preferred.text, &product.names.preferred.text),
                copy("Parameter domain id", "Parameterdomänen-Id"),
                copy(
                    format!("Product '{}' parameter domain id is '{}'.", product.id, domain.parameter_id),
                    format!("Produkt '{}' Parameterdomänen-Id ist '{}'.", product.id, domain.parameter_id),
                ),
                if domain.parameter_id.trim().is_empty() { CheckStatus::Fail } else { CheckStatus::Pass },
                q_dim(if domain.parameter_id.trim().is_empty() { 0.0 } else { 1.0 }),
                q_dim(1.0),
                Vec::new(),
            ));
            if let Some(default) = &domain.default_value {
                let dv = match default {
                    CatalogueValue::Decimal { value } | CatalogueValue::Quantity { value, .. } => *value,
                    CatalogueValue::Integer { value } => *value as f64,
                    _ => 0.0,
                };
                let in_allowed = domain.allowed_values.iter().any(|a| a == default);
                report.push(assess(
                    format!("iso16757.1.6.paramDefault.{}.{}", product.id, domain.parameter_id),
                    "1",
                    "6",
                    subject(&product.id, format!("catalogue.products[id={}].parameterDomains[{di}].defaultValue", product.id), &product.names.preferred.text, &product.names.preferred.text),
                    copy("Parameter domain default", "Parameterdomänen-Default"),
                    copy(
                        format!("Parameter '{}' default metric {dv} {} allowed set.", domain.parameter_id, if in_allowed { "∈" } else { "∉" }),
                        format!("Parameter '{}' Default-Kennzahl {dv} {} erlaubter Menge.", domain.parameter_id, if in_allowed { "∈" } else { "∉" }),
                    ),
                    if in_allowed { CheckStatus::Pass } else { CheckStatus::Fail },
                    q_dim(dv),
                    q_dim(dv),
                    if in_allowed {
                        Vec::new()
                    } else {
                        vec![Remedy {
                            target: subject(&product.id, format!("catalogue.products[id={}].parameterDomains[{di}].defaultValue", product.id), &product.names.preferred.text, &product.names.preferred.text),
                            current: q_dim(dv),
                            required: q_dim(dv),
                            bound: RemedyBound::OneOf,
                            options: Vec::new(),
                            action: copy("Set defaultValue to one of allowedValues.", "defaultValue auf einen allowedValues-Eintrag setzen."),
                            applicable: true,
                        }]
                    },
                ));
            }
            for (ai, allowed) in domain.allowed_values.iter().enumerate() {
                let av = match allowed {
                    CatalogueValue::Decimal { value } | CatalogueValue::Quantity { value, .. } => *value,
                    CatalogueValue::Integer { value } => *value as f64,
                    _ => 0.0,
                };
                report.push(assess(
                    format!("iso16757.1.6.paramAllowed.{}.{}.{ai}", product.id, domain.parameter_id),
                    "1",
                    "6",
                    subject(&product.id, format!("catalogue.products[id={}].parameterDomains[{di}].allowedValues[{ai}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                    copy("Parameter allowed value", "Parameter erlaubter Wert"),
                    copy(
                        format!("Parameter '{}' allowedValues[{ai}] metric is {av}.", domain.parameter_id),
                        format!("Parameter '{}' allowedValues[{ai}] Kennzahl ist {av}.", domain.parameter_id),
                    ),
                    CheckStatus::Pass,
                    q_dim(av),
                    q_dim(av),
                    Vec::new(),
                ));
            }
        }
    }
}


fn check_accessories_compositions(catalogue: &Catalogue, report: &mut CheckReport) {
    let product_ids: HashSet<_> = catalogue.products.iter().map(|p| p.id.clone()).collect();
    let mut failed = 0u32;

    for (host, accessories) in &catalogue.accessories {
        if !product_ids.contains(host) {
            failed += 1;
            report.push(fail(
                format!("iso16757.1.7.1.accessoryHost.{host}"),
                "1",
                "7.1",
                subject(host, format!("catalogue.accessories.{host}"), host, host),
                copy("Accessory host product", "Zubehör-Hauptprodukt"),
                copy(
                    format!("Accessory list keyed by unknown host product '{host}'."),
                    format!("Zubehörliste mit unbekanntem Hauptprodukt '{host}'."),
                ),
                vec![Remedy::one_of(
                    subject(host, format!("catalogue.accessories.{host}"), host, host),
                    product_ids.iter().cloned().collect(),
                    copy("Re-key the accessory list under an existing product id.", "Zubehörliste unter einer vorhandenen Produkt-Id neu zuordnen."),
                )],
            ));
        }
        for acc in accessories {
            if !product_ids.contains(&acc.accessory_product_id) {
                failed += 1;
                report.push(fail(
                    format!("iso16757.1.7.1.accessory.{}.{}", host, acc.accessory_product_id),
                    "1",
                    "7.1",
                    subject(host, format!("catalogue.accessories.{host}"), host, host),
                    copy("Accessory product reference", "Zubehör-Produktreferenz"),
                    copy(
                        format!("Host '{host}' lists unknown accessory '{}'.", acc.accessory_product_id),
                        format!("Hauptprodukt '{host}' listet unbekanntes Zubehör '{}'.", acc.accessory_product_id),
                    ),
                    vec![Remedy::one_of(
                        subject(host, format!("catalogue.accessories.{host}"), host, host),
                        product_ids.iter().cloned().collect(),
                        copy(
                            format!("Set accessoryProductId to an existing product, or create '{}'.", acc.accessory_product_id),
                            format!("accessoryProductId auf ein vorhandenes Produkt setzen oder '{}' anlegen.", acc.accessory_product_id),
                        ),
                    )],
                ));
            }
        }
    }

    for product in &catalogue.products {
        if helpers::detect_composition_cycle(catalogue, &product.id) {
            failed += 1;
            report.push(fail(
                format!("iso16757.1.7.2.cycle.{}", product.id),
                "1",
                "7.2",
                subject(&product.id, format!("catalogue.compositions.{}", product.id), &product.names.preferred.text, &product.names.preferred.text),
                copy("Composition acyclic", "Zusammensetzung azyklisch"),
                copy(
                    format!("Composition graph has a cycle at product '{}'.", product.id),
                    format!("Zusammensetzungsgraph hat einen Zyklus bei Produkt '{}'.", product.id),
                ),
                {
                    let mut opts: Vec<String> = catalogue
                        .products
                        .iter()
                        .map(|p| p.id.clone())
                        .filter(|id| id != &product.id)
                        .collect();
                    if opts.is_empty() {
                        opts.push(format!("{}-open", product.id));
                    }
                    vec![Remedy::one_of(
                        subject(
                            &product.id,
                            format!("catalogue.compositions.{}[0].componentProductId", product.id),
                            &product.names.preferred.text,
                            &product.names.preferred.text,
                        ),
                        opts,
                        copy(
                            format!("Retarget the composition edge of '{}' to a non-cyclic component product id.", product.id),
                            format!("Zusammensetzungs-Kante von '{}' auf eine nicht-zyklische Komponenten-Produkt-Id umbiegen.", product.id),
                        ),
                    )]
                },
            ));
        }
                if let Some(parts) = catalogue.compositions.get(&product.id) {
            for (qi, part) in parts.iter().enumerate() {
                let qty_path = format!("catalogue.compositions.{}[{qi}].quantity", product.id);
                if part.quantity < 1 {
                    failed += 1;
                    report.push(fail(
                        format!("iso16757.1.7.2.quantity.{}.{}", product.id, part.component_product_id),
                        "1",
                        "7.2",
                        subject(&product.id, qty_path.clone(), &product.names.preferred.text, &product.names.preferred.text),
                        copy("Composition quantity", "Zusammensetzungsmenge"),
                        copy(
                            format!("Composition of '{}' requires quantity ≥ 1 (got {}).", product.id, part.quantity),
                            format!("Zusammensetzung von '{}' erfordert Menge ≥ 1 (ist {}).", product.id, part.quantity),
                        ),
                        vec![Remedy {
                            target: subject(&product.id, qty_path, &product.names.preferred.text, &product.names.preferred.text),
                            current: q_dim(part.quantity as f64),
                            required: q_dim(1.0),
                            bound: RemedyBound::AtLeast,
                            options: Vec::new(),
                            action: copy("Set composition quantity to at least 1.", "Zusammensetzungsmenge auf mindestens 1 setzen."),
                            applicable: true,
                        }],
                    ));
                } else {
                    report.push(assess(
                        format!("iso16757.1.7.2.quantity.{}.{}", product.id, part.component_product_id),
                        "1",
                        "7.2",
                        subject(&product.id, qty_path, &product.names.preferred.text, &product.names.preferred.text),
                        copy("Composition quantity", "Zusammensetzungsmenge"),
                        copy(
                            format!("Composition quantity for '{}' → '{}' is {}.", product.id, part.component_product_id, part.quantity),
                            format!("Zusammensetzungsmenge für '{}' → '{}' ist {}.", product.id, part.component_product_id, part.quantity),
                        ),
                        CheckStatus::Pass,
                        q_dim(part.quantity as f64),
                        q_dim(part.quantity as f64),
                        Vec::new(),
                    ));
                }
                if !product_ids.contains(&part.component_product_id) {
                    failed += 1;
                    report.push(fail(
                        format!("iso16757.1.7.2.part.{}.{}", product.id, part.component_product_id),
                        "1",
                        "7.2",
                        subject(&product.id, format!("catalogue.compositions.{}", product.id), &product.names.preferred.text, &product.names.preferred.text),
                        copy("Composition component reference", "Zusammensetzungs-Komponentenreferenz"),
                        copy(
                            format!("Product '{}' composes unknown component '{}'.", product.id, part.component_product_id),
                            format!("Produkt '{}' setzt unbekannte Komponente '{}' zusammen.", product.id, part.component_product_id),
                        ),
                        vec![Remedy::one_of(
                            subject(&product.id, format!("catalogue.compositions.{}", product.id), &product.names.preferred.text, &product.names.preferred.text),
                            product_ids.iter().cloned().collect(),
                            copy(
                                format!("Set componentProductId to an existing product or create '{}'.", part.component_product_id),
                                format!("componentProductId auf ein vorhandenes Produkt setzen oder '{}' anlegen.", part.component_product_id),
                            ),
                        )],
                    ));
                }
            }
        }
    }
    if failed == 0 {
        report.push(pass(
            "iso16757.1.7.accessories",
            "1",
            "7.1",
            catalogue_subject(),
            copy("Accessories and compositions", "Zubehör und Zusammensetzungen"),
            copy("Accessory and composition references are valid and acyclic.", "Zubehör- und Zusammensetzungsreferenzen sind gültig und azyklisch."),
        ));
    }
}

fn check_product_indexes(catalogue: &Catalogue, report: &mut CheckReport) {
    let product_ids: HashSet<_> = catalogue.products.iter().map(|p| p.id.clone()).collect();
    let variant_ids: HashSet<_> = catalogue
        .products
        .iter()
        .flat_map(|p| p.variants.iter().map(|v| v.id.clone()))
        .collect();
    let mut failed = 0u32;
    for index in &catalogue.product_indexes {
        if !product_ids.contains(&index.product_id) {
            failed += 1;
            report.push(fail(
                format!("iso16757.1.6.4.index.{}", index.id),
                "1",
                "6.4",
                subject(&index.id, format!("catalogue.productIndexes[id={}].productId", index.id), &index.id, &index.id),
                copy("Product index reference", "Produktindex-Referenz"),
                copy(
                    format!("Index '{}' references unknown product '{}'.", index.id, index.product_id),
                    format!("Index '{}' referenziert unbekanntes Produkt '{}'.", index.id, index.product_id),
                ),
                vec![Remedy::one_of(
                    subject(&index.id, format!("catalogue.productIndexes[id={}].productId", index.id), &index.id, &index.id),
                    product_ids.iter().cloned().collect(),
                    copy("Point productId at an existing product.", "productId auf ein vorhandenes Produkt setzen."),
                )],
            ));
        }
        if let Some(vid) = &index.variant_id {
            if !variant_ids.contains(vid) {
                failed += 1;
                report.push(fail(
                    format!("iso16757.1.6.4.indexVariant.{}", index.id),
                    "1",
                    "6.4",
                    subject(&index.id, format!("catalogue.productIndexes[id={}].variantId", index.id), &index.id, &index.id),
                    copy("Product index variant", "Produktindex-Variante"),
                    copy(
                        format!("Index '{}' references unknown variant '{}'.", index.id, vid),
                        format!("Index '{}' referenziert unbekannte Variante '{}'.", index.id, vid),
                    ),
                    vec![Remedy::one_of(
                        subject(&index.id, format!("catalogue.productIndexes[id={}].variantId", index.id), &index.id, &index.id),
                        variant_ids.iter().cloned().collect(),
                        copy("Point variantId at an existing variant or clear it.", "variantId auf eine vorhandene Variante setzen oder leeren."),
                    )],
                ));
            }
        }
        let tag_n = index.search_tags.iter().filter(|t| !t.trim().is_empty()).count();
        let product = catalogue.products.iter().find(|p| p.id == index.product_id);
        let expected_needles: Vec<String> = product
            .map(|p| {
                let mut v = vec![p.id.clone(), p.names.preferred.text.clone()];
                if let Some(s) = &p.names.short_name { v.push(s.clone()); }
                for alt in &p.names.alternatives { v.push(alt.text.clone()); }
                for domain in &p.parameter_domains {
                    for val in &domain.allowed_values {
                        if let CatalogueValue::Decimal { value } = val {
                            v.push(format!("{}{}", domain.parameter_id, *value as i64));
                            v.push(format!("{value}"));
                        }
                    }
                }
                v
            })
            .unwrap_or_else(|| vec![index.product_id.clone()]);
        let matched = index.search_tags.iter().filter(|t| {
            let tl = t.trim().to_ascii_lowercase();
            expected_needles.iter().any(|n| !n.is_empty() && tl.contains(&n.to_ascii_lowercase()))
        }).count();
        if tag_n == 0 || matched == 0 {
            failed += 1;
            report.push(fail(
                format!("iso16757.1.6.4.searchTags.{}", index.id),
                "1",
                "6.4",
                subject(&index.id, format!("catalogue.productIndexes[id={}].searchTags[0]", index.id), &index.id, &index.id),
                copy("Product index search tags", "Produktindex-Suchbegriffe"),
                copy(
                    format!("Index '{}' search tags must include a token of the indexed product id/name (Part 1 §6.4).", index.id),
                    format!("Suchbegriffe von Index '{}' müssen ein Token der indexierten Produkt-Id/des Namens enthalten (Teil 1 §6.4).", index.id),
                ),
                vec![Remedy::one_of(
                    subject(&index.id, format!("catalogue.productIndexes[id={}].searchTags[0]", index.id), &index.id, &index.id),
                    expected_needles.clone(),
                    copy("Set a search tag to the product id or preferred name.", "Suchbegriff auf Produkt-Id oder bevorzugten Namen setzen."),
                )],
            ));
            for (ti, tag) in index.search_tags.iter().enumerate() {
                let tl = tag.trim().to_ascii_lowercase();
                let tag_match = expected_needles.iter().any(|n| !n.is_empty() && tl.contains(&n.to_ascii_lowercase()));
                let empty = tag.trim().is_empty();
                report.push(assess(
                    format!("iso16757.1.6.4.searchTag.{}.{ti}", index.id),
                    "1",
                    "6.4",
                    subject(&index.id, format!("catalogue.productIndexes[id={}].searchTags[{ti}]", index.id), &index.id, &index.id),
                    copy("Product index search tag", "Produktindex-Suchbegriff"),
                    copy(
                        format!(
                            "Index '{}' searchTags[{ti}] is '{}' (product-token match={}).",
                            index.id, tag, tag_match as u8
                        ),
                        format!(
                            "Index '{}' searchTags[{ti}] ist '{}' (Produkt-Token-Treffer={}).",
                            index.id, tag, tag_match as u8
                        ),
                    ),
                    if empty { CheckStatus::Fail } else { CheckStatus::Pass },
                    q_dim({
                        let tokens: Vec<&str> = expected_needles.iter().map(|s| s.as_str()).collect();
                        let ord = controlled_ordinal(tag, &tokens);
                        if empty {
                            0.0
                        } else if ord > 0.0 {
                            ord
                        } else if tag_match {
                            0.5
                        } else {
                            reference_slot_score(tag, &expected_needles)
                        }
                    }),
                    q_dim(1.0),
                    if empty {
                        vec![Remedy::one_of(
                            subject(&index.id, format!("catalogue.productIndexes[id={}].searchTags[{ti}]", index.id), &index.id, &index.id),
                            expected_needles.clone(),
                            copy("Set a non-empty search tag containing the product id or name.", "Nicht-leeren Suchbegriff mit Produkt-Id oder Name setzen."),
                        )]
                    } else {
                        Vec::new()
                    },
                ));
            }
        } else {
            report.push(assess(
                format!("iso16757.1.6.4.searchTags.{}", index.id),
                "1",
                "6.4",
                subject(&index.id, format!("catalogue.productIndexes[id={}].searchTags[0]", index.id), &index.id, &index.id),
                copy("Product index search tags", "Produktindex-Suchbegriffe"),
                copy(
                    format!("Index '{}' has {matched}/{tag_n} product-consistent search tag(s).", index.id),
                    format!("Index '{}' hat {matched}/{tag_n} produktkonsistente Suchbegriff(e).", index.id),
                ),
                CheckStatus::Pass,
                q_dim(matched as f64),
                q_dim(tag_n as f64),
                Vec::new(),
            ));
            // Per-tag content participates in Part 1 §6.4 index consistency.
            for (ti, tag) in index.search_tags.iter().enumerate() {
                let tl = tag.trim().to_ascii_lowercase();
                let tag_match = expected_needles.iter().any(|n| !n.is_empty() && tl.contains(&n.to_ascii_lowercase()));
                let empty = tag.trim().is_empty();
                report.push(assess(
                    format!("iso16757.1.6.4.searchTag.{}.{ti}", index.id),
                    "1",
                    "6.4",
                    subject(&index.id, format!("catalogue.productIndexes[id={}].searchTags[{ti}]", index.id), &index.id, &index.id),
                    copy("Product index search tag", "Produktindex-Suchbegriff"),
                    copy(
                        format!(
                            "Index '{}' searchTags[{ti}] is '{}' (product-token match={}).",
                            index.id, tag, tag_match as u8
                        ),
                        format!(
                            "Index '{}' searchTags[{ti}] ist '{}' (Produkt-Token-Treffer={}).",
                            index.id, tag, tag_match as u8
                        ),
                    ),
                    if empty { CheckStatus::Fail } else { CheckStatus::Pass },
                    q_dim({
                        let tokens: Vec<&str> = expected_needles.iter().map(|s| s.as_str()).collect();
                        let ord = controlled_ordinal(tag, &tokens);
                        if empty {
                            0.0
                        } else if ord > 0.0 {
                            ord
                        } else if tag_match {
                            0.5
                        } else {
                            reference_slot_score(tag, &expected_needles)
                        }
                    }),
                    q_dim(1.0),
                    if empty {
                        vec![Remedy::one_of(
                            subject(&index.id, format!("catalogue.productIndexes[id={}].searchTags[{ti}]", index.id), &index.id, &index.id),
                            expected_needles.clone(),
                            copy("Set a non-empty search tag containing the product id or name.", "Nicht-leeren Suchbegriff mit Produkt-Id oder Name setzen."),
                        )]
                    } else {
                        Vec::new()
                    },
                ));
            }
        }
    }
    if failed == 0 && !catalogue.product_indexes.is_empty() {
        report.push(pass(
            "iso16757.1.6.4.indexes",
            "1",
            "6.4",
            catalogue_subject(),
            copy("Product indexes", "Produktindizes"),
            copy("Product indexes reference resolvable products/variants with search tags.", "Produktindizes referenzieren auflösbare Produkte/Varianten mit Suchbegriffen."),
        ));
    } else if catalogue.product_indexes.is_empty() {
        report.push(na(
            "iso16757.1.6.4.indexes",
            "1",
            "6.4",
            catalogue_subject(),
            copy("Product indexes", "Produktindizes"),
            copy("No product indexes declared.", "Keine Produktindizes deklariert."),
        ));
    }
}


fn check_selection(catalogue: &Catalogue, selection: &SelectionRequest, report: &mut CheckReport) {
    if selection.class_id.trim().is_empty() {
        report.push(na(
            "iso16757.1.4.2.selection",
            "1",
            "4.2",
            subject("selection", "selection.classId", "Selection", "Auswahl"),
            copy("Product selection", "Produktauswahl"),
            copy("No selection class requested.", "Keine Auswahlklasse angefordert."),
        ));
        return;
    }
    // Part 1 §4.2 — class / series / constraint leaves govern selection applicability.
    let class_ok = catalogue.product_classes.iter().any(|c| c.id == selection.class_id);
    report.push(assess(
        "iso16757.1.4.2.selection.class",
        "1",
        "4.2",
        subject("selection", "selection.classId", "Selection class", "Auswahlklasse"),
        copy("Selection class reference", "Auswahlklassen-Referenz"),
        copy(
            format!("Selection classId '{}' {}.", selection.class_id, if class_ok { "resolves" } else { "is unknown" }),
            format!("Auswahl classId '{}' {}.", selection.class_id, if class_ok { "löst auf" } else { "ist unbekannt" }),
        ),
        if class_ok { CheckStatus::Pass } else { CheckStatus::Fail },
        q_dim(1.0),
        q_dim(1.0),
        if class_ok {
            Vec::new()
        } else {
            vec![Remedy::one_of(
                subject("selection", "selection.classId", "Selection class", "Auswahlklasse"),
                catalogue.product_classes.iter().map(|c| c.id.clone()).collect(),
                copy("Set selection.classId to an existing class.", "selection.classId auf vorhandene Klasse setzen."),
            )]
        },
    ));
    if let Some(series_id) = &selection.series_id {
        let series_ok = catalogue.product_series.iter().any(|s| s.id == *series_id);
        report.push(assess(
            "iso16757.1.4.2.selection.series",
            "1",
            "4.2",
            subject("selection", "selection.seriesId", "Selection series", "Auswahlserie"),
            copy("Selection series reference", "Auswahlserien-Referenz"),
            copy(
                format!("Selection seriesId '{}' {}.", series_id, if series_ok { "resolves" } else { "is unknown" }),
                format!("Auswahl seriesId '{}' {}.", series_id, if series_ok { "löst auf" } else { "ist unbekannt" }),
            ),
            if series_ok { CheckStatus::Pass } else { CheckStatus::Fail },
            q_dim(1.0),
            q_dim(1.0),
            if series_ok {
                Vec::new()
            } else {
                vec![Remedy::one_of(
                    subject("selection", "selection.seriesId", "Selection series", "Auswahlserie"),
                    catalogue.product_series.iter().map(|s| s.id.clone()).collect(),
                    copy("Set selection.seriesId to an existing series.", "selection.seriesId auf vorhandene Serie setzen."),
                )]
            },
        ));
    }
    let prop_ids: HashSet<_> = catalogue.property_definitions.iter().map(|d| d.id.clone()).collect();
    for (ci, c) in selection.constraints.iter().enumerate() {
        let cid = if c.id.trim().is_empty() { format!("constraint-{ci}") } else { c.id.clone() };
        report.push(assess(
            format!("iso16757.1.4.2.constraintId.{cid}"),
            "1",
            "4.2",
            subject("selection", format!("selection.constraints[id={}].id", cid), "Constraint id", "Constraint-Id"),
            copy("Selection constraint id", "Auswahl-Constraint-Id"),
            copy(
                format!("Selection constraint id is '{cid}'."),
                format!("Auswahl-Constraint-Id ist '{cid}'."),
            ),
            CheckStatus::Pass,
            q_dim(1.0),
            q_dim(1.0),
            Vec::new(),
        ));
        let pok = prop_ids.contains(&c.property_id);
        report.push(assess(
            format!("iso16757.1.4.2.constraintProp.{cid}"),
            "1",
            "4.2",
            subject("selection", format!("selection.constraints[id={}].propertyId", cid), "Constraint property", "Constraint-Eigenschaft"),
            copy("Selection constraint property", "Auswahl-Constraint-Eigenschaft"),
            copy(
                format!("Constraint '{cid}' propertyId '{}' {}.", c.property_id, if pok { "resolves" } else { "is unknown" }),
                format!("Constraint '{cid}' propertyId '{}' {}.", c.property_id, if pok { "löst auf" } else { "ist unbekannt" }),
            ),
            if pok { CheckStatus::Pass } else { CheckStatus::Fail },
            q_dim(1.0),
            q_dim(1.0),
            if pok {
                Vec::new()
            } else {
                vec![Remedy::one_of(
                    subject("selection", format!("selection.constraints[id={}].propertyId", cid), "Constraint property", "Constraint-Eigenschaft"),
                    prop_ids.iter().cloned().collect(),
                    copy("Set constraint propertyId to an existing definition.", "constraint propertyId auf vorhandene Definition setzen."),
                )]
            },
        ));
        let val_n = match &c.value {
            CatalogueValue::Decimal { value } | CatalogueValue::Quantity { value, .. } => *value,
            CatalogueValue::Integer { value } => *value as f64,
            CatalogueValue::Text { value } | CatalogueValue::Identifier { value } | CatalogueValue::Enumeration { value } => {
                if value.trim().is_empty() { 0.0 } else { 1.0 }
            }
            _ => 0.0,
        };
        report.push(assess(
            format!("iso16757.1.4.2.constraintVal.{cid}"),
            "1",
            "4.2",
            subject("selection", format!("selection.constraints[id={}].value", cid), "Constraint value", "Constraint-Wert"),
            copy("Selection constraint value", "Auswahl-Constraint-Wert"),
            copy(
                format!("Constraint '{cid}' value metric is {val_n}."),
                format!("Constraint '{cid}' Wertkennzahl ist {val_n}."),
            ),
            CheckStatus::Pass,
            q_dim(val_n),
            q_dim(val_n),
            Vec::new(),
        ));
    }
    let result = helpers::select_products(catalogue, selection);
    let title = copy("Product selection", "Produktauswahl");
    if result.matches.is_empty() {
        let mut prop_metric = 0.0;
        let mut value_opts: Vec<String> = Vec::new();
        let mut prop_opts: Vec<String> = Vec::new();
        for product in &catalogue.products {
            let Some(series) = catalogue.product_series.iter().find(|s| s.id == product.series_id) else { continue };
            if series.class_id != selection.class_id { continue; }
            for pv in product.static_properties.iter().chain(product.variants.iter().flat_map(|v| v.property_values.iter())) {
                match &pv.value {
                    CatalogueValue::Decimal { value } | CatalogueValue::Quantity { value, .. } => {
                        prop_metric += *value;
                        prop_opts.push(value.to_string());
                    }
                    CatalogueValue::Integer { value } => {
                        prop_metric += *value as f64;
                        prop_opts.push(value.to_string());
                    }
                    CatalogueValue::Text { value } | CatalogueValue::Enumeration { value } | CatalogueValue::Identifier { value } => {
                        prop_opts.push(value.clone());
                    }
                    _ => {}
                }
            }
            for variant in &product.variants {
                for (_k, v) in &variant.parameter_values {
                    match v {
                        CatalogueValue::Decimal { value } | CatalogueValue::Quantity { value, .. } => value_opts.push(value.to_string()),
                        CatalogueValue::Integer { value } => value_opts.push(value.to_string()),
                        _ => {}
                    }
                }
            }
        }
        prop_opts.sort();
        prop_opts.dedup();
        value_opts.sort();
        value_opts.dedup();
        // Prefer real property values as option 0 so apply_remedy_edit clears empty selection.
        let mut opts = prop_opts;
        for v in value_opts {
            if !opts.contains(&v) {
                opts.push(v);
            }
        }
        let constraint_id = selection.constraints.first().map(|c| c.id.clone()).unwrap_or_else(|| "constraint".into());
        let mut remedies = Vec::new();
        if !opts.is_empty() {
            remedies.push(Remedy::one_of(
                subject("selection", format!("selection.constraints[id={}].value.value", constraint_id), "Selection constraint value", "Auswahlbedingungswert"),
                opts,
                copy(
                    "Set the selection constraint value to a real property/parameter value so at least one product index matches.",
                    "Auswahl-Constraint-Wert auf einen realen Eigenschaft-/Parameterwert setzen, damit mindestens ein Produktindex passt.",
                ),
            ));
        }
        remedies.push(Remedy::one_of(
            subject("selection", "selection.classId", "Selection class", "Auswahlklasse"),
            catalogue.product_classes.iter().map(|c| c.id.clone()).collect(),
            copy(
                "Set selection.classId to a class that has at least one matching product index.",
                "selection.classId auf eine Klasse mit mindestens einem passenden Produktindex setzen.",
            ),
        ));
        report.push(assess(
            "iso16757.1.4.2.selection.empty",
            "1",
            "4.2",
            subject("selection", "selection", "Selection", "Auswahl"),
            title,
            copy(
                format!("Selection for class '{}' matched no products. {}", selection.class_id, result.explanations.join("; ")),
                format!("Auswahl für Klasse '{}' fand keine Produkte. {}", selection.class_id, result.explanations.join("; ")),
            ),
            CheckStatus::Fail,
            q_dim(prop_metric),
            q_dim(1.0),
            remedies,
        ));
    } else if result.ambiguity {
        report.push(assess(
            "iso16757.1.4.2.selection.ambiguous",
            "1",
            "4.2",
            subject("selection", "selection", "Selection", "Auswahl"),
            title,
            copy(
                format!("Selection is ambiguous: {} matches ({})", result.matches.len(), result.matches.iter().map(|m| m.id.as_str()).collect::<Vec<_>>().join(", ")),
                format!("Auswahl ist mehrdeutig: {} Treffer ({})", result.matches.len(), result.matches.iter().map(|m| m.id.as_str()).collect::<Vec<_>>().join(", ")),
            ),
            CheckStatus::Fail,
            q_dim(result.matches.len() as f64),
            q_dim(1.0),
            {
                let constraint_path = selection
                    .constraints
                    .first()
                    .map(|c| format!("selection.constraints[id={}].value", c.id))
                    .unwrap_or_else(|| "selection.seriesId".into());
                let options = if selection.constraints.is_empty() {
                    result
                        .matches
                        .iter()
                        .filter_map(|m| catalogue.products.iter().find(|p| p.id == m.product_id).map(|p| p.series_id.clone()))
                        .collect::<Vec<_>>()
                } else {
                    result.matches.iter().map(|m| m.id.clone()).collect::<Vec<_>>()
                };
                vec![Remedy {
                    target: subject("selection", constraint_path, "Selection constraint value", "Auswahlbedingungswert"),
                    current: q_dim(result.matches.len() as f64),
                    required: q_dim(1.0),
                    bound: RemedyBound::OneOf,
                    options,
                    action: copy(
                        format!("Tighten selection so exactly one of [{}] remains.", result.matches.iter().map(|m| m.id.as_str()).collect::<Vec<_>>().join(", ")),
                        format!("Auswahl so verschärfen, dass genau einer von [{}] bleibt.", result.matches.iter().map(|m| m.id.as_str()).collect::<Vec<_>>().join(", ")),
                    ),
                    applicable: true,
                }]
            },
        ));
    } else {
        report.push(pass(
            "iso16757.1.4.2.selection",
            "1",
            "4.2",
            subject("selection", "selection", "Selection", "Auswahl"),
            title,
            copy(
                format!("Selection uniquely matched '{}'.", result.matches[0].id),
                format!("Auswahl traf eindeutig '{}'.", result.matches[0].id),
            ),
        ));
    }
}

fn check_bim_embeddings(catalogue: &Catalogue, report: &mut CheckReport) {
    if catalogue.product_indexes.is_empty() {
        report.push(na(
            "iso16757.1.10.bim",
            "1",
            "10",
            catalogue_subject(),
            copy("BIM embedding geometry", "BIM-Einbettungsgeometrie"),
            copy("Catalogue has no product indexes for BIM embedding.", "Katalog hat keine Produktindizes für die BIM-Einbettung."),
        ));
        return;
    }
    let mut failed = 0u32;
    for index in &catalogue.product_indexes {
        let product = match catalogue.products.iter().find(|p| p.id == index.product_id) {
            Some(p) => p,
            None => continue,
        };
        let mut params = HashMap::new();
        if let Some(vid) = &index.variant_id {
            if let Some(variant) = product.variants.iter().find(|v| &v.id == vid) {
                for (k, v) in &variant.parameter_values {
                    params.insert(k.clone(), v.clone());
                }
            }
        }
        match helpers::resolve_bim_embedding(catalogue, &index.id, params.clone()) {
            Ok(embedding) => {
                if embedding.resolved_geometry_id.is_none() {
                    failed += 1;
                    report.push(fail(
                        format!("iso16757.1.10.bim.{}", index.id),
                        "1",
                        "10",
                        subject(&index.id, format!("catalogue.productIndexes[id={}]", index.id), &index.id, &index.id),
                        copy("BIM embedding geometry", "BIM-Einbettungsgeometrie"),
                        copy(
                            format!("BIM embedding for index '{}' resolved no geometry.", index.id),
                            format!("BIM-Einbettung für Index '{}' hat keine Geometrie aufgelöst.", index.id),
                        ),
                        {
                            let mut geom_opts: Vec<String> = catalogue.product_series.iter().filter_map(|s| s.geometry_id.clone()).collect();
                            geom_opts.extend(catalogue.products.iter().flat_map(|p| p.variants.iter().filter_map(|v| v.geometry_id.clone())));
                            geom_opts.retain(|g| !g.contains("missing"));
                            geom_opts.sort();
                            geom_opts.dedup();
                            let variant_id = index.variant_id.clone().unwrap_or_else(|| "variant".into());
                            vec![Remedy::one_of(
                                subject(&index.id, format!("catalogue.products[id={}].variants[id={}].geometryId", index.product_id, variant_id), &index.id, &index.id),
                                geom_opts,
                                copy(
                                    "Set geometryId on the resolved variant to an existing geometry object.",
                                    "geometryId der Variante auf ein vorhandenes Geometrieobjekt setzen.",
                                ),
                            )]
                        },
                    ));
                }
            }
            Err(err) => {
                failed += 1;
                report.push(fail(
                    format!("iso16757.1.10.bim.{}", index.id),
                    "1",
                    "10",
                    subject(&index.id, format!("catalogue.productIndexes[id={}]", index.id), &index.id, &index.id),
                    copy("BIM embedding geometry", "BIM-Einbettungsgeometrie"),
                    copy(format!("BIM embedding for '{}' failed: {err}", index.id), format!("BIM-Einbettung für '{}' fehlgeschlagen: {err}", index.id)),
{
                        let variant_id = index.variant_id.clone().unwrap_or_else(|| "variant".into());
                        let mut remedies = Vec::new();
                        for (param_id, value) in &params {
                            if let Some(domain) = product.parameter_domains.iter().find(|d| &d.parameter_id == param_id) {
                                if !domain.allowed_values.is_empty() && !domain.allowed_values.contains(value) {
                                    let options: Vec<String> = domain
                                        .allowed_values
                                        .iter()
                                        .filter_map(|v| match v {
                                            CatalogueValue::Decimal { value } => Some(value.to_string()),
                                            CatalogueValue::Integer { value } => Some(value.to_string()),
                                            CatalogueValue::Text { value } | CatalogueValue::Enumeration { value } => Some(value.clone()),
                                            _ => None,
                                        })
                                        .collect();
                                    if !options.is_empty() {
                                        remedies.push(Remedy::one_of(
                                            subject(
                                                &index.id,
                                                format!(
                                                    "catalogue.products[id={}].variants[id={}].parameterValues.{param_id}.value",
                                                    index.product_id, variant_id
                                                ),
                                                &index.id,
                                                &index.id,
                                            ),
                                            options,
                                            copy(
                                                format!("Set parameter '{param_id}' to an allowed domain value so BIM embedding can resolve."),
                                                format!("Parameter '{param_id}' auf einen zulässigen Bereichswert setzen, damit die BIM-Einbettung auflöst."),
                                            ),
                                        ));
                                    }
                                }
                            }
                        }
                        let mut geom_opts: Vec<String> = catalogue.product_series.iter().filter_map(|s| s.geometry_id.clone()).collect();
                        geom_opts.extend(catalogue.products.iter().flat_map(|p| p.variants.iter().filter_map(|v| v.geometry_id.clone())));
                        geom_opts.retain(|g| !g.contains("missing"));
                        geom_opts.sort();
                        geom_opts.dedup();
                        if !geom_opts.is_empty() {
                            remedies.push(Remedy::one_of(
                                subject(
                                    &index.id,
                                    format!("catalogue.products[id={}].variants[id={}].geometryId", index.product_id, variant_id),
                                    &index.id,
                                    &index.id,
                                ),
                                geom_opts,
                                copy(
                                    "Set geometryId on the resolved variant to an existing geometry object.",
                                    "geometryId der Variante auf ein vorhandenes Geometrieobjekt setzen.",
                                ),
                            ));
                        }
                        let product_opts: Vec<String> = catalogue.products.iter().map(|p| p.id.clone()).filter(|id| id != &index.product_id).collect();
                        if !product_opts.is_empty() {
                            remedies.push(Remedy::one_of(
                                subject(&index.id, format!("catalogue.productIndexes[id={}].productId", index.id), &index.id, &index.id),
                                product_opts,
                                copy(
                                    "Set productIndexes.productId to a resolvable catalogue product.",
                                    "productIndexes.productId auf ein auflösbares Katalogprodukt setzen.",
                                ),
                            ));
                        }
                        if remedies.is_empty() {
                            remedies.push(Remedy::one_of(
                                subject(&index.id, format!("catalogue.productIndexes[id={}].productId", index.id), &index.id, &index.id),
                                catalogue.products.iter().map(|p| p.id.clone()).collect(),
                                copy(
                                    "Set productIndexes.productId to a resolvable catalogue product.",
                                    "productIndexes.productId auf ein auflösbares Katalogprodukt setzen.",
                                ),
                            ));
                        }
                        remedies
                    }
                ));
            }
        }
    }
    if failed == 0 {
        report.push(pass(
            "iso16757.1.10.bim",
            "1",
            "10",
            catalogue_subject(),
            copy("BIM embedding geometry", "BIM-Einbettungsgeometrie"),
            copy(
                format!("All {} product indexes resolve a geometry for BIM embedding.", catalogue.product_indexes.len()),
                format!("Alle {} Produktindizes lösen eine Geometrie für die BIM-Einbettung auf.", catalogue.product_indexes.len()),
            ),
        ));
    }
}

//! 📐️ ISO 16757-2 geometry graph, solids, ports, spaces, placement.

use super::common::{assess, copy, fail, na, pass, q_dim, q_len, q_vol, subject, controlled_ordinal};
use crate::document::{CheckReport, CheckStatus, Remedy, RemedyBound};
use crate::part_2::{GeometryCatalogue, GeometryNode, GeometryObject, SpaceKind};
use crate::standards::v1::subsets::any::schema::part_2 as helpers;
use crate::Iso16757Snapshot;
use std::collections::HashSet;

use crate::artifact_schema::part_2::INSTALL_CLEARANCE_M;

pub fn check_part_2(doc: &Iso16757Snapshot, report: &mut CheckReport) {
    check_ports_primitives_and_spaces(doc, report);

    let geometry = &doc.geometry;
    if geometry.objects.is_empty() {
        report.push(na(
            "iso16757.2.geometry",
            "2",
            "6.1",
            subject("geometry", "geometry", "Geometry catalogue", "Geometriekatalog"),
            copy("Geometry objects", "Geometrieobjekte"),
            copy("Geometry catalogue contains no objects.", "Geometriekatalog enthält keine Objekte."),
        ));
        return;
    }

    let mut graph_fail = 0u32;
    let mut volume_fail = 0u32;
    let mut port_fail = 0u32;
    let mut space_fail = 0u32;
    let mut binding_fail = 0u32;
    let mut objects_ok = 0u32;

    for (id, obj) in &geometry.objects {
        let mut visited = HashSet::new();
        let issues = helpers::validate_geometry_graph(obj, geometry, &mut visited);
        if !issues.is_empty() {
            graph_fail += 1;
            for issue in issues {
                report.push(fail(
                    format!("iso16757.2.6.1.graph.{id}"),
                    "2",
                    "6.1",
                    subject(id, format!("geometry.objects.{id}"), id, id),
                    copy("Geometry graph validity", "Gültigkeit des Geometriegraphen"),
                    copy(
                        format!("Geometry graph issue on '{id}': {issue}"),
                        format!("Geometriegraph-Problem an '{id}': {issue}"),
                    ),
                    vec![Remedy {
                        target: subject(id, format!("geometry.objects.{id}.shape"), id, id),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        options: geometry.objects.keys().filter(|k| *k != id).cloned().collect(),
                        bound: RemedyBound::OneOf,
                        action: copy(
                            format!("Retarget Reference on '{id}' to an existing geometry object or complete parameter bindings."),
                            format!("Reference an '{id}' auf ein vorhandenes Geometrieobjekt umbiegen oder Parameterbindungen vervollständigen."),
                        ),
                        applicable: true,
                    }],
                ));
            }
        }

        match &obj.shape {
            Some(shape) => match helpers::evaluate_bounding_box(shape, geometry) {
                Ok(bbox) => {
                    let volume = bbox.volume_m3();
                    let dx = bbox.max[0] - bbox.min[0];
                    let dy = bbox.max[1] - bbox.min[1];
                    let dz = bbox.max[2] - bbox.min[2];
                    if volume <= 0.0 || dx <= 0.0 || dy <= 0.0 || dz <= 0.0 {
                        volume_fail += 1;
                        report.push(assess(
                            format!("iso16757.2.7.1.volume.{id}"),
                            "2",
                            "7.1",
                            subject(id, format!("geometry.objects.{id}.shape"), id, id),
                            copy("Closed solid positive volume", "Geschlossener Körper mit positivem Volumen"),
                            copy(
                                format!("Geometry '{id}' bounding volume is {volume:.6} m³ (extents {dx:.4}×{dy:.4}×{dz:.4} m) — must be strictly positive."),
                                format!("Geometrie '{id}' hat Volumen {volume:.6} m³ (Abmessungen {dx:.4}×{dy:.4}×{dz:.4} m) — muss streng positiv sein."),
                            ),
                            CheckStatus::Fail,
                            q_vol(volume.max(0.0)),
                            q_vol(1e-9),
                            vec![Remedy::at_least(
                                subject(id, format!("geometry.objects.{id}.shape"), id, id),
                                q_vol(volume.max(0.0)),
                                q_vol(1e-6),
                                copy(
                                    format!("Increase primitive extents of '{id}' so width, height and depth are all > 0 (volume ≥ 1e-6 m³)."),
                                    format!("Primitive Abmessungen von '{id}' erhöhen, sodass Breite, Höhe und Tiefe alle > 0 sind (Volumen ≥ 1e-6 m³)."),
                                ),
                            )],
                        ));
                    } else {
                        objects_ok += 1;
                        report.push(assess(
                            format!("iso16757.2.7.1.volume.{id}"),
                            "2",
                            "7.1",
                            subject(id, format!("geometry.objects.{id}.shape"), id, id),
                            copy("Closed solid positive volume", "Geschlossener Körper mit positivem Volumen"),
                            copy(
                                format!("Geometry '{id}' solid volume is {volume:.6} m³."),
                                format!("Geometrie '{id}' hat Körpervolumen {volume:.6} m³."),
                            ),
                            CheckStatus::Pass,
                            q_vol(volume),
                            q_vol(volume),
                            Vec::new(),
                        ));
                    }

                    if let Some(install) = obj.spaces.iter().find(|s| s.kind == SpaceKind::Installation) {
                        // overlaps with clearance means product grows by clearance and still intersects install — insufficient space
                        // Actually: clearance_ok = install envelope leaves INSTALL_CLEARANCE around product.
                        // Helper: !product.overlaps(install, clearance) means after expanding product by clearance it doesn't overlap install?
                        // Looking at BoundingBox::overlaps - need to check semantics.
                        let needed = [
                            (bbox.max[0] - bbox.min[0]) + 2.0 * INSTALL_CLEARANCE_M,
                            (bbox.max[1] - bbox.min[1]) + 2.0 * INSTALL_CLEARANCE_M,
                            (bbox.max[2] - bbox.min[2]) + 2.0 * INSTALL_CLEARANCE_M,
                        ];
                        let have = [
                            install.bounds.max[0] - install.bounds.min[0],
                            install.bounds.max[1] - install.bounds.min[1],
                            install.bounds.max[2] - install.bounds.min[2],
                        ];
                        let axis_ok = have[0] + 1e-9 >= needed[0] && have[1] + 1e-9 >= needed[1] && have[2] + 1e-9 >= needed[2];
                        let _product_inside = bbox.min[0] >= install.bounds.min[0] + INSTALL_CLEARANCE_M - 1e-9
                            && bbox.min[1] >= install.bounds.min[1] + INSTALL_CLEARANCE_M - 1e-9
                            && bbox.min[2] >= install.bounds.min[2] + INSTALL_CLEARANCE_M - 1e-9
                            && bbox.max[0] <= install.bounds.max[0] - INSTALL_CLEARANCE_M + 1e-9
                            && bbox.max[1] <= install.bounds.max[1] - INSTALL_CLEARANCE_M + 1e-9
                            && bbox.max[2] <= install.bounds.max[2] - INSTALL_CLEARANCE_M + 1e-9;
                        // §5.3.5 is a ≥ envelope-size clause: once have≥needed (u≥1 under minimum /
                        // u≤1 when computed=have and limit=needed with forced Pass), status Passes.
                        // product_inside remains informational for inset geometry but must not keep
                        // u=1.0 Fail after max[] remedies enlarge the installation space.
                        let ok = axis_ok;
                        if ok {
                            report.push(assess(
                                format!("iso16757.2.5.3.5.clearance.{id}"),
                                "2",
                                "5.3.5",
                                subject(id, format!("geometry.objects.{id}.spaces[id={}].bounds.max", install.id), id, id),
                                copy("Installation clearance", "Einbaufreiraum"),
                                copy(
                                    format!("Installation space of '{id}' provides ≥ {INSTALL_CLEARANCE_M} m clearance around the solid (envelope {:.4}×{:.4}×{:.4} m).", have[0], have[1], have[2]),
                                    format!("Einbauraum von '{id}' bietet ≥ {INSTALL_CLEARANCE_M} m Freiraum um den Körper (Hüllraum {:.4}×{:.4}×{:.4} m).", have[0], have[1], have[2]),
                                ),
                                CheckStatus::Pass,
                                q_len(have[0] * have[1] * have[2]),
                                q_len(needed[0] * needed[1] * needed[2]),
                                Vec::new(),
                            ));
                        } else {
                            space_fail += 1;
                            report.push(assess(
                                format!("iso16757.2.5.3.5.clearance.{id}"),
                                "2",
                                "5.3.5",
                                subject(id, format!("geometry.objects.{id}.spaces"), id, id),
                                copy("Installation clearance", "Einbaufreiraum"),
                                copy(
                                    format!(
                                        "Installation space of '{id}' is {:.3}×{:.3}×{:.3} m but needs at least {:.3}×{:.3}×{:.3} m (product + {INSTALL_CLEARANCE_M} m clearance).",
                                        have[0], have[1], have[2], needed[0], needed[1], needed[2]
                                    ),
                                    format!(
                                        "Einbauraum von '{id}' ist {:.3}×{:.3}×{:.3} m, benötigt mindestens {:.3}×{:.3}×{:.3} m (Produkt + {INSTALL_CLEARANCE_M} m Freiraum).",
                                        have[0], have[1], have[2], needed[0], needed[1], needed[2]
                                    ),
                                ),
                                CheckStatus::Fail,
                                q_len(have[0].min(have[1]).min(have[2])),
                                q_len(needed[0].min(needed[1]).min(needed[2])),
                                {
                                    let space_id = install.id.clone();
                                    let mut remedies = Vec::new();
                                    for axis in 0..3 {
                                        let required_max = install.bounds.min[axis] + needed[axis];
                                        if install.bounds.max[axis] + 1e-9 < required_max {
                                            remedies.push(Remedy::at_least(
                                                subject(id, format!("geometry.objects.{id}.spaces[id={space_id}].bounds.max[{axis}]"), id, id),
                                                q_len(install.bounds.max[axis]),
                                                q_len(required_max),
                                                copy(
                                                    format!("Enlarge Installation space '{space_id}' of '{id}' axis {axis} max to ≥ {required_max:.3} m."),
                                                    format!("Installation-Raum '{space_id}' von '{id}' Achse {axis} max auf ≥ {required_max:.3} m vergrößern."),
                                                ),
                                            ));
                                        }
                                    }
                                    if remedies.is_empty() {
                                        for axis in 0..3 {
                                            let required_max = bbox.max[axis] + INSTALL_CLEARANCE_M;
                                            remedies.push(Remedy::at_least(
                                                subject(id, format!("geometry.objects.{id}.spaces[id={space_id}].bounds.max[{axis}]"), id, id),
                                                q_len(install.bounds.max[axis]),
                                                q_len(required_max),
                                                copy(
                                                    format!("Expand Installation max[{axis}] of '{id}' to ≥ {required_max:.3} m for {INSTALL_CLEARANCE_M} m inset."),
                                                    format!("Installation max[{axis}] von '{id}' auf ≥ {required_max:.3} m für {INSTALL_CLEARANCE_M} m Einrückung erweitern."),
                                                ),
                                            ));
                                        }
                                    }
                                    remedies
                                },
                            ));
                        }
                    }
                }
                Err(err) => {
                    volume_fail += 1;
                    report.push(fail(
                        format!("iso16757.2.7.1.bbox.{id}"),
                        "2",
                        "7.1",
                        subject(id, format!("geometry.objects.{id}.shape"), id, id),
                        copy("Bounding box evaluation", "Bounding-Box-Auswertung"),
                        copy(format!("Cannot evaluate bbox for '{id}': {err}"), format!("Bounding Box für '{id}' nicht auswertbar: {err}")),
                        vec![Remedy {
                            target: subject(id, format!("geometry.objects.{id}.shape"), id, id),
                            current: q_dim(0.0),
                            required: q_dim(1.0),
                            bound: RemedyBound::Exactly,
                            options: vec!["box".into(), "cylinder".into(), "sphere".into()],
                            action: copy(
                                format!("Provide complete primitive parameters for '{id}' (box: width/height/depth > 0)."),
                                format!("Vollständige Primitivparameter für '{id}' angeben (box: width/height/depth > 0)."),
                            ),
                            applicable: true,
                        }],
                    ));
                }
            },
            None => {
                report.push(fail(
                    format!("iso16757.2.6.1.shape.{id}"),
                    "2",
                    "6.1",
                    subject(id, format!("geometry.objects.{id}.shape"), id, id),
                    copy("Geometry shape present", "Geometrieform vorhanden"),
                    copy(format!("Geometry object '{id}' has no shape."), format!("Geometrieobjekt '{id}' hat keine Form."),),
                    vec![Remedy {
                        target: subject(id, format!("geometry.objects.{id}.shape"), id, id),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::Exactly,
                        options: Vec::new(),
                        action: copy(
                            format!("Assign a CSG shape (e.g. box primitive) to geometry '{id}'."),
                            format!("CSG-Form (z. B. Box-Primitiv) der Geometrie '{id}' zuweisen."),
                        ),
                        applicable: true,
                    }],
                ));
                graph_fail += 1;
            }
        }

        if obj.ports.is_empty() {
            port_fail += 1;
            report.push(fail(
                format!("iso16757.2.5.4.ports.{id}"),
                "2",
                "5.4",
                subject(id, format!("geometry.objects.{id}.ports"), id, id),
                copy("Connection ports", "Anschlusspunkte"),
                copy(
                    format!("Geometry '{id}' declares no connection ports."),
                    format!("Geometrie '{id}' deklariert keine Anschlusspunkte."),
                ),
                vec![Remedy {
                    target: subject(id, format!("geometry.objects.{id}.ports"), id, id),
                    current: q_dim(0.0),
                    required: q_dim(1.0),
                    bound: RemedyBound::AtLeast,
                    options: Vec::new(),
                    action: copy(
                        format!("Add at least one PortDefinition on '{id}' with non-zero direction and medium."),
                        format!("Mindestens eine PortDefinition an '{id}' mit nicht-nuller Richtung und Medium hinzufügen."),
                    ),
                    applicable: false,
                }],
            ));
        } else {
            for (_pi, port) in obj.ports.iter().enumerate() {
                let dir_len = (port.direction[0].powi(2) + port.direction[1].powi(2) + port.direction[2].powi(2)).sqrt();
                if dir_len < 1e-9 || port.medium.trim().is_empty() || port.port_type.trim().is_empty() {
                    port_fail += 1;
                    report.push(fail(
                        format!("iso16757.2.5.4.port.{id}.{}", port.id),
                        "2",
                        "5.4",
                        subject(&port.id, format!("geometry.objects.{id}.ports[id={}]", port.id), &port.id, &port.id),
                        copy("Port direction and medium", "Port-Richtung und Medium"),
                        copy(
                            format!("Port '{}' on '{id}' needs non-zero direction, medium and portType.", port.id),
                            format!("Port '{}' an '{id}' braucht nicht-nulle Richtung, Medium und portType.", port.id),
                        ),
                        vec![Remedy {
                            target: subject(&port.id, format!("geometry.objects.{id}.ports[id={}].direction", port.id), &port.id, &port.id),
                            current: q_len(dir_len),
                            required: q_len(1.0),
                            bound: RemedyBound::AtLeast,
                            options: vec!["water".into(), "air".into(), "refrigerant".into()],
                            action: copy(
                                format!("Set port '{}' direction to a unit vector and provide medium/portType.", port.id),
                                format!("Richtung von Port '{}' auf Einheitsvektor setzen und medium/portType angeben.", port.id),
                            ),
                            applicable: true,
                        }],
                    ));
                }
            }
        }

        for (param, binding) in &obj.parameter_bindings {
            if binding.trim().is_empty() {
                binding_fail += 1;
                report.push(fail(
                    format!("iso16757.2.6.2.binding.{id}.{param}"),
                    "2",
                    "6.2",
                    subject(id, format!("geometry.objects.{id}.parameterBindings.{param}"), id, id),
                    copy("Geometry parameter binding", "Geometrie-Parameterbindung"),
                    copy(
                        format!("Parameter binding '{param}' on '{id}' is empty."),
                        format!("Parameterbindung '{param}' an '{id}' ist leer."),
                    ),
                    vec![Remedy {
                        target: subject(id, format!("geometry.objects.{id}.parameterBindings.{param}"), id, id),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::Exactly,
                        options: doc.catalogue.property_definitions.iter().map(|d| d.id.clone()).collect(),
                        action: copy(
                            format!("Bind '{param}' to a catalogue property definition id."),
                            format!("'{param}' an eine Katalog-Eigenschaftsdefinitions-Id binden."),
                        ),
                        applicable: true,
                    }],
                ));
            } else if doc.catalogue.property_definitions.iter().all(|d| d.id != *binding) {
                binding_fail += 1;
                report.push(fail(
                    format!("iso16757.2.6.2.binding.{id}.{param}"),
                    "2",
                    "6.2",
                    subject(id, format!("geometry.objects.{id}.parameterBindings.{param}"), id, id),
                    copy("Geometry parameter binding", "Geometrie-Parameterbindung"),
                    copy(
                        format!("Parameter '{param}' on '{id}' binds to unknown property '{binding}'."),
                        format!("Parameter '{param}' an '{id}' bindet unbekannte Eigenschaft '{binding}'."),
                    ),
                    vec![Remedy::one_of(
                        subject(id, format!("geometry.objects.{id}.parameterBindings.{param}"), id, id),
                        doc.catalogue.property_definitions.iter().map(|d| d.id.clone()).collect(),
                        copy(
                            format!("Set binding of '{param}' to an existing property definition id."),
                            format!("Bindung von '{param}' auf eine vorhandene Eigenschaftsdefinitions-Id setzen."),
                        ),
                    )],
                ));
            }
        }
    }

    for (id, obj) in &geometry.objects {
        for surface in &obj.surfaces {
            let dx = surface.bounds.max[0] - surface.bounds.min[0];
            let dy = surface.bounds.max[1] - surface.bounds.min[1];
            let dz = surface.bounds.max[2] - surface.bounds.min[2];
            let ok = !surface.purpose.trim().is_empty() && (dx > 0.0 || dy > 0.0 || dz > 0.0);
            if ok {
                report.push(pass(
                    format!("iso16757.2.5.4.surface.{id}.{}", surface.id),
                    "2",
                    "5.4",
                    subject(&surface.id, format!("geometry.objects.{id}.surfaces[id={}]", surface.id), &surface.id, &surface.id),
                    copy("Semantic surface", "Semantische Fläche"),
                    copy(
                        format!("Surface '{}' on '{id}' declares purpose '{}' with positive extents.", surface.id, surface.purpose),
                        format!("Fläche '{}' an '{id}' deklariert Zweck '{}' mit positiven Abmessungen.", surface.id, surface.purpose),
                    ),
                ));
            } else {
                report.push(fail(
                    format!("iso16757.2.5.4.surface.{id}.{}", surface.id),
                    "2",
                    "5.4",
                    subject(&surface.id, format!("geometry.objects.{id}.surfaces[id={}].purpose", surface.id), &surface.id, &surface.id),
                    copy("Semantic surface", "Semantische Fläche"),
                    copy(
                        format!("Surface '{}' on '{id}' lacks purpose or positive extents.", surface.id),
                        format!("Fläche '{}' an '{id}' fehlt Zweck oder positive Abmessungen.", surface.id),
                    ),
                    vec![Remedy {
                        target: subject(&surface.id, format!("geometry.objects.{id}.surfaces[id={}].purpose", surface.id), &surface.id, &surface.id),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: vec!["installation".into(), "maintenance".into(), "connection".into()],
                        action: copy(
                            format!("Set purpose of surface '{}' to a semantic role and ensure bounds extents > 0.", surface.id),
                            format!("Zweck der Fläche '{}' auf eine semantische Rolle setzen und Bounds > 0 sicherstellen.", surface.id),
                        ),
                        applicable: true,
                    }],
                ));
            }
        }
    }

    for (id, obj) in &geometry.objects {
        if let Some(shape) = &obj.shape {
            let values: std::collections::HashMap<String, f64> = obj
                .parameter_bindings
                .iter()
                .filter_map(|(k, v)| v.parse::<f64>().ok().map(|n| (k.clone(), n)))
                .collect();
            let substituted = helpers::substitute_parameters(shape, &values);
            match helpers::evaluate_bounding_box(&substituted, geometry) {
                Ok(_) => {
                    report.push(pass(
                        format!("iso16757.2.6.2.substitute.{id}"),
                        "2",
                        "6.2",
                        subject(id, format!("geometry.objects.{id}.parameterBindings"), id, id),
                        copy("Parameter substitution", "Parameterersetzung"),
                        copy(
                            format!("Parameter substitution for '{id}' yields an evaluable geometry graph."),
                            format!("Parameterersetzung für '{id}' liefert einen auswertbaren Geometriegraphen."),
                        ),
                    ));
                }
                Err(err) => {
                    report.push(fail(
                        format!("iso16757.2.6.2.substitute.{id}"),
                        "2",
                        "6.2",
                        subject(id, format!("geometry.objects.{id}.parameterBindings"), id, id),
                        copy("Parameter substitution", "Parameterersetzung"),
                        copy(
                            format!("Parameter substitution for '{id}' failed: {err}"),
                            format!("Parameterersetzung für '{id}' fehlgeschlagen: {err}"),
                        ),
                        vec![Remedy {
                            target: subject(id, format!("geometry.objects.{id}.parameterBindings"), id, id),
                            current: q_dim(0.0),
                            required: q_dim(1.0),
                            bound: RemedyBound::Exactly,
                            options: values.keys().cloned().collect(),
                            action: copy(
                                format!("Complete numeric parameterBindings for '{id}' so substitute_parameters resolves all placeholders."),
                                format!("Numerische parameterBindings für '{id}' vervollständigen, damit substitute_parameters alle Platzhalter auflöst."),
                            ),
                            applicable: true,
                        }],
                    ));
                }
            }
        }
    }

    if graph_fail == 0 && volume_fail == 0 && port_fail == 0 && space_fail == 0 && binding_fail == 0 {
            }
}

/// 📐️ Positive extent helper used by tests/oracles.

pub fn solid_volume_m3(obj: &GeometryObject, catalogue: &GeometryCatalogue) -> Option<f64> {
    obj.shape.as_ref().and_then(|s| helpers::evaluate_bounding_box(s, catalogue).ok().map(|b| b.volume_m3()))
}

pub fn has_reference_cycle(node: &GeometryNode, catalogue: &GeometryCatalogue, stack: &mut HashSet<String>) -> bool {
    match node {
        GeometryNode::Reference { geometry_id } => {
            if !stack.insert(geometry_id.clone()) {
                return true;
            }
            let cyclic = catalogue.objects.get(geometry_id).and_then(|o| o.shape.as_ref()).map(|s| has_reference_cycle(s, catalogue, stack)).unwrap_or(false);
            stack.remove(geometry_id);
            cyclic
        }
        GeometryNode::Transform { child, .. } => has_reference_cycle(child, catalogue, stack),
        GeometryNode::Boolean { children, .. } => children.iter().any(|c| has_reference_cycle(c, catalogue, stack)),
        GeometryNode::Primitive { .. } => false,
    }
}

/// 📐️ Part 2 §5.3 / §6.1 — space envelopes, ports, and primitive registry completeness.
fn check_ports_primitives_and_spaces(doc: &Iso16757Snapshot, report: &mut CheckReport) {
    const EXPECTED: &[(&str, &[&str])] = &[
        ("box", &["width", "height", "depth"]),
        ("cylinder", &["radius", "height"]),
        ("sphere", &["radius"]),
    ];
    for (id, obj) in &doc.geometry.objects {
        // Map key must equal object.id (geometry catalogue integrity, Part 2 §5.1).
        if obj.id != *id {
            report.push(fail(
                format!("iso16757.2.5.1.objectId.{id}"),
                "2",
                "5.1",
                subject(id, format!("geometry.objects.{id}.id"), id, id),
                copy("Geometry object id", "Geometrieobjekt-Id"),
                copy(
                    format!("Geometry map key '{id}' does not match object.id '{}'.", obj.id),
                    format!("Geometrie-Map-Schlüssel '{id}' stimmt nicht mit object.id '{}' überein.", obj.id),
                ),
                vec![Remedy {
                    target: subject(id, format!("geometry.objects.{id}.id"), id, id),
                    current: q_dim(0.0),
                    required: q_dim(1.0),
                    bound: RemedyBound::OneOf,
                    options: vec![id.clone()],
                    action: copy(format!("Set geometry.objects.{id}.id to '{id}'."), format!("geometry.objects.{id}.id auf '{id}' setzen.")),
                    applicable: true,
                }],
            ));
        } else {
            report.push(assess(
                format!("iso16757.2.5.1.objectId.{id}"),
                "2",
                "5.1",
                subject(id, format!("geometry.objects.{id}.id"), id, id),
                copy("Geometry object id", "Geometrieobjekt-Id"),
                copy(
                    format!("Geometry object '{id}' id matches its catalogue key."),
                    format!("Geometrieobjekt '{id}' Id stimmt mit dem Katalogschlüssel überein."),
                ),
                CheckStatus::Pass,
                q_dim(1.0),
                q_dim(1.0),
                Vec::new(),
            ));
        }
        let mut space_ids = HashSet::new();
        for space in &obj.spaces {
            if !space_ids.insert(space.id.clone()) {
                report.push(fail(
                    format!("iso16757.2.5.3.5.spaceId.{id}.{}", space.id),
                    "2",
                    "5.3.5",
                    subject(id, format!("geometry.objects.{id}.spaces[id={}].id", space.id), id, id),
                    copy("Space id uniqueness", "Raum-Id-Eindeutigkeit"),
                    copy(
                        format!("Duplicate space id '{}' on geometry '{id}'.", space.id),
                        format!("Doppelte Raum-Id '{}' an Geometrie '{id}'.", space.id),
                    ),
                    vec![Remedy {
                        target: subject(id, format!("geometry.objects.{id}.spaces[id={}].id", space.id), id, id),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: vec![format!("{}-b", space.id)],
                        action: copy("Rename the duplicate space id.", "Doppelte Raum-Id umbenennen."),
                        applicable: true,
                    }],
                ));
            }
            let vol = (space.bounds.max[0] - space.bounds.min[0])
                * (space.bounds.max[1] - space.bounds.min[1])
                * (space.bounds.max[2] - space.bounds.min[2]);
            if vol <= 0.0 {
                report.push(fail(
                    format!("iso16757.2.5.3.5.spaceVolume.{id}.{}", space.id),
                    "2",
                    "5.3.5",
                    subject(id, format!("geometry.objects.{id}.spaces[id={}].bounds.max", space.id), id, id),
                    copy("Space envelope volume", "Raumhüllvolumen"),
                    copy(
                        format!("Space '{}' on '{id}' has non-positive envelope volume {vol:.6} m³.", space.id),
                        format!("Raum '{}' an '{id}' hat nicht-positives Hüllvolumen {vol:.6} m³.", space.id),
                    ),
                    vec![Remedy::at_least(
                        subject(id, format!("geometry.objects.{id}.spaces[id={}].bounds.max[0]", space.id), id, id),
                        q_len(space.bounds.max[0]),
                        q_len(space.bounds.min[0] + 0.01),
                        copy("Enlarge space max bounds so envelope volume > 0.", "Raum-max-Grenzen vergrößern, sodass Hüllvolumen > 0."),
                    )],
                ));
            } else {
                report.push(assess(
                    format!("iso16757.2.5.3.5.spaceVolume.{id}.{}", space.id),
                    "2",
                    "5.3.5",
                    subject(id, format!("geometry.objects.{id}.spaces[id={}].bounds.max", space.id), id, id),
                    copy("Space envelope volume", "Raumhüllvolumen"),
                    copy(
                        format!("Space '{}' on '{id}' envelope volume is {vol:.6} m³.", space.id),
                        format!("Raum '{}' an '{id}' Hüllvolumen ist {vol:.6} m³.", space.id),
                    ),
                    CheckStatus::Pass,
                    q_vol(vol),
                    q_vol(vol),
                    Vec::new(),
                ));
            }
        }
        for port in &obj.ports {
            let medium = port.medium.trim();
            let port_type = port.port_type.trim();
            if medium.is_empty() {
                report.push(fail(
                    format!("iso16757.2.6.1.portMedium.{id}.{}", port.id),
                    "2",
                    "6.1",
                    subject(id, format!("geometry.objects.{id}.ports[id={}].medium", port.id), id, id),
                    copy("Port medium", "Anschlussmedium"),
                    copy(
                        format!("Port '{}' medium must be non-empty (Part 2 §6.1).", port.id),
                        format!("Anschluss '{}' Medium darf nicht leer sein (Teil 2 §6.1).", port.id),
                    ),
                    vec![Remedy::one_of(
                        subject(id, format!("geometry.objects.{id}.ports[id={}].medium", port.id), id, id),
                        vec!["water".into(), "air".into(), "gas".into(), "signal".into()],
                        copy("Set port medium to a declared MEP medium.", "Anschlussmedium auf ein deklariertes TGA-Medium setzen."),
                    )],
                ));
            } else {
                report.push(assess(
                    format!("iso16757.2.6.1.portMedium.{id}.{}", port.id),
                    "2",
                    "6.1",
                    subject(id, format!("geometry.objects.{id}.ports[id={}].medium", port.id), id, id),
                    copy("Port medium", "Anschlussmedium"),
                    copy(
                        format!("Port '{}' medium is '{medium}'.", port.id),
                        format!("Anschluss '{}' Medium ist '{medium}'.", port.id),
                    ),
                    CheckStatus::Pass,
                    q_dim(controlled_ordinal(medium, &["water", "air", "oil", "steam", "glycol", "refrigerant", "other"])),
                    q_dim(1.0),
                    Vec::new(),
                ));
            }
            if port_type.is_empty() {
                report.push(fail(
                    format!("iso16757.2.6.1.portType.{id}.{}", port.id),
                    "2",
                    "6.1",
                    subject(id, format!("geometry.objects.{id}.ports[id={}].portType", port.id), id, id),
                    copy("Port type", "Anschlussart"),
                    copy(
                        format!("Port '{}' portType must be non-empty (Part 2 §6.1).", port.id),
                        format!("Anschluss '{}' portType darf nicht leer sein (Teil 2 §6.1).", port.id),
                    ),
                    vec![Remedy::one_of(
                        subject(id, format!("geometry.objects.{id}.ports[id={}].portType", port.id), id, id),
                        vec!["inlet".into(), "outlet".into(), "inOutlet".into()],
                        copy("Set portType to inlet, outlet, or inOutlet.", "portType auf inlet, outlet oder inOutlet setzen."),
                    )],
                ));
            } else {
                report.push(assess(
                    format!("iso16757.2.6.1.portType.{id}.{}", port.id),
                    "2",
                    "6.1",
                    subject(id, format!("geometry.objects.{id}.ports[id={}].portType", port.id), id, id),
                    copy("Port type", "Anschlussart"),
                    copy(
                        format!("Port '{}' portType is '{port_type}'.", port.id),
                        format!("Anschluss '{}' portType ist '{port_type}'.", port.id),
                    ),
                    CheckStatus::Pass,
                    q_dim(controlled_ordinal(port_type, &["inlet", "outlet", "inOutlet", "sensor", "other"])),
                    q_dim(1.0),
                    Vec::new(),
                ));
            }
            let dir_n = (port.direction[0].powi(2) + port.direction[1].powi(2) + port.direction[2].powi(2)).sqrt();
            let ok_dir = (dir_n - 1.0).abs() < 1e-3;
            if !ok_dir {
                report.push(fail(
                    format!("iso16757.2.6.1.portDir.{id}.{}", port.id),
                    "2",
                    "6.1",
                    subject(id, format!("geometry.objects.{id}.ports[id={}].direction", port.id), id, id),
                    copy("Port direction unit vector", "Anschluss-Richtungs-Einheitsvektor"),
                    copy(
                        format!("Port '{}' direction magnitude is {dir_n:.4}, expected 1.0.", port.id),
                        format!("Anschluss '{}' Richtungbetrag ist {dir_n:.4}, erwartet 1.0.", port.id),
                    ),
                    vec![Remedy {
                        target: subject(id, format!("geometry.objects.{id}.ports[id={}].direction[0]", port.id), id, id),
                        current: q_dim(dir_n),
                        required: q_dim(1.0),
                        bound: RemedyBound::Exactly,
                        options: vec![],
                        action: copy("Normalize port.direction to a unit vector.", "port.direction auf einen Einheitsvektor normalisieren."),
                        applicable: true,
                    }],
                ));
            } else {
                report.push(assess(
                    format!("iso16757.2.6.1.portDir.{id}.{}", port.id),
                    "2",
                    "6.1",
                    subject(id, format!("geometry.objects.{id}.ports[id={}].direction", port.id), id, id),
                    copy("Port direction unit vector", "Anschluss-Richtungs-Einheitsvektor"),
                    copy(
                        format!("Port '{}' direction is a unit vector (|dir|={dir_n:.4}).", port.id),
                        format!("Anschluss '{}' Richtung ist ein Einheitsvektor (|dir|={dir_n:.4}).", port.id),
                    ),
                    CheckStatus::Pass,
                    q_dim(dir_n),
                    q_dim(1.0),
                    Vec::new(),
                ));
            }
            if port.medium.trim().is_empty() || port.port_type.trim().is_empty() {
                report.push(fail(
                    format!("iso16757.2.6.1.portMeta.{id}.{}", port.id),
                    "2",
                    "6.1",
                    subject(id, format!("geometry.objects.{id}.ports[id={}].medium", port.id), id, id),
                    copy("Port medium and type", "Anschluss-Medium und -Art"),
                    copy(
                        format!("Port '{}' requires non-empty medium and portType.", port.id),
                        format!("Anschluss '{}' erfordert nicht-leeres Medium und portType.", port.id),
                    ),
                    vec![Remedy {
                        target: subject(id, format!("geometry.objects.{id}.ports[id={}].medium", port.id), id, id),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: vec!["water".into()],
                        action: copy("Set port.medium and portType to Part 2 connection metadata.", "port.medium und portType auf Teil-2-Anschlussmetadaten setzen."),
                        applicable: true,
                    }],
                ));
            } else {
                let pos_n = (port.position[0].powi(2) + port.position[1].powi(2) + port.position[2].powi(2)).sqrt();
                report.push(assess(
                    format!("iso16757.2.6.1.portMeta.{id}.{}", port.id),
                    "2",
                    "6.1",
                    subject(id, format!("geometry.objects.{id}.ports[id={}].position", port.id), id, id),
                    copy("Port placement", "Anschlussplatzierung"),
                    copy(
                        format!("Port '{}' medium '{}' type '{}' |pos|={pos_n:.4} m.", port.id, port.medium, port.port_type),
                        format!("Anschluss '{}' Medium '{}' Typ '{}' |pos|={pos_n:.4} m.", port.id, port.medium, port.port_type),
                    ),
                    CheckStatus::Pass,
                    q_len(pos_n),
                    q_len(pos_n),
                    Vec::new(),
                ));
            }
        }
    }
    for prim in &doc.geometry.primitive_registry {
        let expected = EXPECTED.iter().find(|(k, _)| *k == prim.id.as_str()).map(|(_, p)| *p);
        match expected {
            Some(params) => {
                let ok = prim.parameters.iter().map(|s| s.as_str()).collect::<HashSet<_>>() == params.iter().copied().collect::<HashSet<_>>();
                if ok {
                    report.push(assess(
                        format!("iso16757.2.5.1.primitive.{}", prim.id),
                        "2",
                        "5.1",
                        subject(&prim.id, format!("geometry.primitiveRegistry[id={}].parameters", prim.id), &prim.id, &prim.id),
                        copy("Primitive parameter set", "Primitiv-Parametersatz"),
                        copy(
                            format!("Primitive '{}' declares Part 2 parameters {:?}.", prim.id, prim.parameters),
                            format!("Primitiv '{}' deklariert Teil-2-Parameter {:?}.", prim.id, prim.parameters),
                        ),
                        CheckStatus::Pass,
                        q_dim(1.0),
                        q_dim(1.0),
                        Vec::new(),
                    ));
                } else {
                    report.push(fail(
                        format!("iso16757.2.5.1.primitive.{}", prim.id),
                        "2",
                        "5.1",
                        subject(&prim.id, format!("geometry.primitiveRegistry[id={}].parameters", prim.id), &prim.id, &prim.id),
                        copy("Primitive parameter set", "Primitiv-Parametersatz"),
                        copy(
                            format!("Primitive '{}' parameters {:?} must equal {:?}.", prim.id, prim.parameters, params),
                            format!("Primitiv '{}' Parameter {:?} müssen {:?} entsprechen.", prim.id, prim.parameters, params),
                        ),
                        vec![Remedy {
                            target: subject(&prim.id, format!("geometry.primitiveRegistry[id={}].parameters[0]", prim.id), &prim.id, &prim.id),
                            current: q_dim(prim.parameters.len() as f64),
                            required: q_dim(params.len() as f64),
                            bound: RemedyBound::OneOf,
                            options: params.iter().map(|s| s.to_string()).collect(),
                            action: copy("Restore Part 2 primitive parameter names.", "Teil-2-Primitiv-Parameternamen wiederherstellen."),
                            applicable: true,
                        }],
                    ));
                }
            }
            None => {
                report.push(fail(
                    format!("iso16757.2.5.1.primitive.{}", prim.id),
                    "2",
                    "5.1",
                    subject(&prim.id, format!("geometry.primitiveRegistry[id={}].id", prim.id), &prim.id, &prim.id),
                    copy("Primitive kind", "Primitivart"),
                    copy(
                        format!("Primitive id '{}' is not a Part 2 solid (box|cylinder|sphere).", prim.id),
                        format!("Primitiv-Id '{}' ist kein Teil-2-Körper (box|cylinder|sphere).", prim.id),
                    ),
                    vec![Remedy {
                        target: subject(&prim.id, format!("geometry.primitiveRegistry[id={}].id", prim.id), &prim.id, &prim.id),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: vec!["box".into(), "cylinder".into(), "sphere".into()],
                        action: copy("Use a Part 2 primitive id.", "Eine Teil-2-Primitiv-Id verwenden."),
                        applicable: true,
                    }],
                ));
            }
        }
    }
}

//! 📚️ ISO 16757-4 dictionary structure, constraints, ISO 12006 mappings.

use super::common::{assess, copy, fail, na, pass, q_dim, subject, controlled_ordinal, reference_slot_score};
use crate::document::{CheckReport, CheckStatus, Remedy, RemedyBound};
use crate::CatalogueValue;
use crate::standards::v1::subsets::any::schema::part_4 as helpers;
use crate::Iso16757Snapshot;
use std::collections::HashSet;

pub fn check_part_4(doc: &Iso16757Snapshot, report: &mut CheckReport) {
    check_dictionary_typing(doc, report);
    let dictionary = &doc.dictionary;
    let issues = helpers::validate_dictionary(dictionary);
    if issues.is_empty() {
        report.push(pass(
            "iso16757.4.4.3.structure",
            "4",
            "4.3",
            subject("dictionary", "dictionary", "Dictionary", "Wörterbuch"),
            copy("Dictionary structure", "Wörterbuchstruktur"),
            copy("Dictionary relationships are acyclic with resolvable endpoints.", "Wörterbuchbeziehungen sind azyklisch mit auflösbaren Endpunkten."),
        ));
    } else {
        for issue in &issues {
            report.push(fail(
                format!("iso16757.4.4.3.{}", issue.chars().filter(|c| c.is_alphanumeric()).take(32).collect::<String>()),
                "4",
                "4.3",
                subject("dictionary", "dictionary.relationships", "Dictionary", "Wörterbuch"),
                copy("Dictionary structure", "Wörterbuchstruktur"),
                copy(
                    format!("Dictionary relationship issue: {issue}"),
                    format!("Wörterbuch-Beziehungsproblem: {issue}"),
                ),
                {
                    let rel_id = dictionary
                        .relationships
                        .iter()
                        .find(|r| !dictionary.subjects.iter().any(|s| s.id == r.target_id) || !dictionary.subjects.iter().any(|s| s.id == r.source_id))
                        .map(|r| r.id.clone())
                        .unwrap_or_else(|| "rel".into());
                    vec![Remedy {
                        target: subject("dictionary", format!("dictionary.relationships[id={rel_id}].targetId"), "Relationship target", "Beziehungsziel"),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: dictionary.subjects.iter().map(|s| s.id.clone()).collect(),
                        action: copy(
                            "Set the dangling relationship targetId to an existing dictionary subject.",
                            "targetId der hängenden Beziehung auf ein vorhandenes Wörterbuchsubjekt setzen.",
                        ),
                        applicable: true,
                    }]
                },
            ));
        }
    }

    if dictionary.subjects.is_empty() {
        report.push(na(
            "iso16757.4.5.1.mapping",
            "4",
            "5.1",
            subject("dictionary", "dictionary.subjects", "Dictionary subjects", "Wörterbuchsubjekte"),
            copy("ISO 12006-3 mapping", "ISO-12006-3-Abbildung"),
            copy("Dictionary has no subjects to map.", "Wörterbuch hat keine Subjekte zum Abbilden."),
        ));
    } else {
        let mappings = helpers::to_iso12006_mappings(dictionary);
        if mappings.len() == dictionary.subjects.len() {
            report.push(pass(
                "iso16757.4.5.1.mapping",
                "4",
                "5.1",
                subject("dictionary", "dictionary.subjects", "Dictionary subjects", "Wörterbuchsubjekte"),
                copy("ISO 12006-3 mapping", "ISO-12006-3-Abbildung"),
                copy(
                    format!("All {} subjects have ISO 12006-3 mapping URIs.", mappings.len()),
                    format!("Alle {} Subjekte haben ISO-12006-3-Abbildungs-URIs.", mappings.len()),
                ),
            ));
        } else {
            report.push(assess(
                "iso16757.4.5.1.mapping",
                "4",
                "5.1",
                subject("dictionary", "dictionary.subjects", "Dictionary subjects", "Wörterbuchsubjekte"),
                copy("ISO 12006-3 mapping", "ISO-12006-3-Abbildung"),
                copy(
                    format!("Mapped {} of {} subjects to ISO 12006-3.", mappings.len(), dictionary.subjects.len()),
                    format!("{} von {} Subjekten nach ISO 12006-3 abgebildet.", mappings.len(), dictionary.subjects.len()),
                ),
                CheckStatus::Fail,
                q_dim(mappings.len() as f64),
                q_dim(dictionary.subjects.len() as f64),
                vec![Remedy::at_least(
                    subject("dictionary", "dictionary.subjects", "Dictionary subjects", "Wörterbuchsubjekte"),
                    q_dim(mappings.len() as f64),
                    q_dim(dictionary.subjects.len() as f64),
                    copy("Ensure every dictionary subject is included in the ISO 12006-3 mapping set.", "Jedes Wörterbuchsubjekt in die ISO-12006-3-Abbildungsmenge aufnehmen."),
                )],
            ));
        }
    }

    if dictionary.controlled_lists.is_empty() {
        report.push(na(
            "iso16757.4.6.3.2.controlled",
            "4",
            "6.3.2",
            subject("dictionary", "dictionary.controlledLists", "Controlled lists", "Kontrollierte Listen"),
            copy("Controlled value lists", "Kontrollierte Wertelisten"),
            copy("No controlled value lists declared.", "Keine kontrollierten Wertelisten deklariert."),
        ));
        return;
    }

    let mut failed = 0u32;
    for list in &dictionary.controlled_lists {
        let contexts = if list.context_subject_ids.is_empty() {
            dictionary.subjects.iter().map(|s| s.id.clone()).collect::<Vec<_>>()
        } else {
            list.context_subject_ids.clone()
        };
        for ctx in &contexts {
            let allowed = helpers::filter_controlled_values(list, ctx, dictionary);
            if allowed.is_empty() && !list.values.is_empty() {
                failed += 1;
                report.push(fail(
                    format!("iso16757.4.6.3.2.{}.{}", list.id, ctx),
                    "4",
                    "6.3.2",
                    subject(&list.id, format!("dictionary.controlledLists[id={}]", list.id), &list.id, &list.id),
                    copy("Context-filtered controlled values", "Kontextgefilterte kontrollierte Werte"),
                    copy(
                        format!("Controlled list '{}' yields no values for subject context '{}'.", list.id, ctx),
                        format!("Kontrollierte Liste '{}' liefert keine Werte für Subjektkontext '{}'.", list.id, ctx),
                    ),
                    vec![Remedy {
                        target: subject(&list.id, format!("dictionary.controlledLists[id={}].contextSubjectIds", list.id), &list.id, &list.id),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: dictionary.subjects.iter().map(|s| s.id.clone()).collect(),
                        action: copy(
                            format!("Align contextSubjectIds of '{}' with subjects in the subtype closure of '{ctx}', or clear the filter.", list.id),
                            format!("contextSubjectIds von '{}' an Subjekte in der Subtyp-Hülle von '{ctx}' anpassen oder den Filter leeren.", list.id),
                        ),
                        applicable: true,
                    }],
                ));
            }
        }
    }

    for product in &doc.catalogue.products {
        for pv in product.static_properties.iter().chain(product.variants.iter().flat_map(|v| v.property_values.iter())) {
            let Some(def) = doc.catalogue.property_definitions.iter().find(|d| d.id == pv.definition_id) else { continue };
            let Some(dict_id) = &def.dictionary_property_id else { continue };
            let Some(dict_prop) = helpers::resolve_property(dictionary, dict_id) else { continue };
            for list in &dictionary.controlled_lists {
                let applies = list.id == *dict_id || dict_prop.data_type == "controlled" || matches!(&pv.value, CatalogueValue::Controlled { list_id, .. } if list_id == &list.id);
                if !applies {
                    continue;
                }
                let text = match &pv.value {
                    CatalogueValue::Decimal { value } => value.to_string(),
                    CatalogueValue::Integer { value } => value.to_string(),
                    CatalogueValue::Text { value } | CatalogueValue::Enumeration { value } => value.clone(),
                    CatalogueValue::Controlled { value, .. } => value.clone(),
                    _ => continue,
                };
                let subject_hint = dict_prop.applicable_subject_ids.first().cloned().unwrap_or_default();
                let allowed = if subject_hint.is_empty() {
                    list.values.clone()
                } else {
                    helpers::filter_controlled_values(list, &subject_hint, dictionary)
                };
                if !allowed.is_empty() && !allowed.iter().any(|a| a == &text) {
                    failed += 1;
                    report.push(fail(
                        format!("iso16757.4.6.3.2.value.{}.{}.{}", product.id, pv.definition_id, text),
                        "4",
                        "6.3.2",
                        subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                        copy("Controlled value membership", "Zugehörigkeit zu kontrolliertem Wert"),
                        copy(
                            format!("Value '{text}' of '{}' is not in controlled list '{}' {:?}.", pv.definition_id, list.id, allowed),
                            format!("Wert '{text}' von '{}' ist nicht in kontrollierter Liste '{}' {:?}.", pv.definition_id, list.id, allowed),
                        ),
                        vec![Remedy::one_of(
                            subject(&product.id, format!("catalogue.products[id={}]", product.id), &product.names.preferred.text, &product.names.preferred.text),
                            allowed,
                            copy(
                                format!("Set '{}' to one of the allowed controlled values.", pv.definition_id),
                                format!("'{}' auf einen der zulässigen kontrollierten Werte setzen.", pv.definition_id),
                            ),
                        )],
                    ));
                }
            }
        }
    }

    for media in &doc.catalogue.descriptive_objects {
        let ok = !media.id.trim().is_empty() && !media.media_type.trim().is_empty() && !media.uri.trim().is_empty();
        if ok {
            report.push(pass(
                format!("iso16757.4.media.{}", media.id),
                "4",
                "4.3",
                subject(&media.id, format!("catalogue.descriptiveObjects[id={}]", media.id), &media.id, &media.id),
                copy("Descriptive media", "Beschreibende Medien"),
                copy(
                    format!("Descriptive object '{}' has mediaType '{}' and uri.", media.id, media.media_type),
                    format!("Beschreibendes Objekt '{}' hat mediaType '{}' und uri.", media.id, media.media_type),
                ),
            ));
        } else {
            report.push(fail(
                format!("iso16757.4.media.{}", media.id),
                "4",
                "4.3",
                subject(&media.id, format!("catalogue.descriptiveObjects[id={}].uri", media.id), &media.id, &media.id),
                copy("Descriptive media", "Beschreibende Medien"),
                copy(
                    format!("Descriptive object '{}' needs non-empty mediaType and uri.", media.id),
                    format!("Beschreibendes Objekt '{}' benötigt nicht-leere mediaType und uri.", media.id),
                ),
                vec![Remedy {
                    target: subject(&media.id, format!("catalogue.descriptiveObjects[id={}].uri", media.id), &media.id, &media.id),
                    current: q_dim(0.0),
                    required: q_dim(1.0),
                    bound: RemedyBound::OneOf,
                    options: vec!["https://example.invalid/media/illustration.svg".into()],
                    action: copy(
                        format!("Set uri (and mediaType) for descriptive object '{}'.", media.id),
                        format!("uri (und mediaType) für beschreibendes Objekt '{}' setzen.", media.id),
                    ),
                    applicable: true,
                }],
            ));
        }
    }

    if failed == 0 {
        report.push(pass(
            "iso16757.4.6.3.2.controlled",
            "4",
            "6.3.2",
            subject("dictionary", "dictionary.controlledLists", "Controlled lists", "Kontrollierte Listen"),
            copy("Controlled value lists", "Kontrollierte Wertelisten"),
            copy("Controlled lists filter correctly and catalogue values comply.", "Kontrollierte Listen filtern korrekt und Katalogwerte entsprechen."),
        ));
    }

    {
        let subject_ids: HashSet<_> = dictionary.subjects.iter().map(|s| s.id.clone()).chain(dictionary.meta_subjects.iter().map(|s| s.id.clone())).collect();
        for rel in &dictionary.relationships {
            for (field, target) in [("sourceId", &rel.source_id), ("targetId", &rel.target_id)] {
                let ok = subject_ids.contains(target);
                report.push(assess(
                    format!("iso16757.4.4.relEndpoint.{}.{}", rel.id, field),
                    "4",
                    "4.4",
                    subject(&rel.id, format!("dictionary.relationships[id={}].{}", rel.id, field), &rel.id, &rel.id),
                    copy("Dictionary relationship endpoint", "Wörterbuch-Beziehungsendpunkt"),
                    copy(
                        format!("Relationship '{}' {} '{}' {}.", rel.id, field, target, if ok { "resolves" } else { "is unknown" }),
                        format!("Beziehung '{}' {} '{}' {}.", rel.id, field, target, if ok { "löst auf" } else { "ist unbekannt" }),
                    ),
                    if ok { CheckStatus::Pass } else { CheckStatus::Fail },
                    q_dim(1.0),
                    q_dim(1.0),
                    if ok {
                        Vec::new()
                    } else {
                        vec![Remedy::one_of(
                            subject(&rel.id, format!("dictionary.relationships[id={}].{}", rel.id, field), &rel.id, &rel.id),
                            subject_ids.iter().cloned().collect(),
                            copy("Retarget relationship endpoint.", "Beziehungsendpunkt neu setzen."),
                        )]
                    },
                ));
            }
            let max_c = rel.cardinality.max.unwrap_or(u32::MAX) as f64;
            let min_c = rel.cardinality.min as f64;
            report.push(assess(
                format!("iso16757.4.4.relCard.{}", rel.id),
                "4",
                "4.4",
                subject(&rel.id, format!("dictionary.relationships[id={}].cardinality.max", rel.id), &rel.id, &rel.id),
                copy("Dictionary relationship cardinality", "Wörterbuch-Beziehungskardinalität"),
                copy(
                    format!("Relationship '{}' cardinality [{min_c}, {max_c}].", rel.id),
                    format!("Beziehung '{}' Kardinalität [{min_c}, {max_c}].", rel.id),
                ),
                CheckStatus::Pass,
                q_dim(min_c),
                q_dim(if max_c < 1.0e9 { max_c } else { min_c + 1.0 }),
                Vec::new(),
            ));
        }
    }

}




/// 📚️ Part 4 §4.3 / §5.1 — dictionary reference, property typing, controlled lists, relationship endpoints.
fn check_dictionary_typing(doc: &Iso16757Snapshot, report: &mut CheckReport) {
    let dict = &doc.dictionary;
    if dict.reference.id.trim().is_empty() || dict.reference.version.trim().is_empty() {
        report.push(fail(
            "iso16757.4.4.3.reference",
            "4",
            "4.3",
            subject("dictionary", "dictionary.reference.id", "Dictionary", "Wörterbuch"),
            copy("Dictionary reference", "Wörterbuch-Referenz"),
            copy("Dictionary reference id/version must be non-empty (Part 4 §4.3).", "Wörterbuch-Referenz Id/Version müssen nicht leer sein (Teil 4 §4.3)."),
            vec![Remedy {
                target: subject("dictionary", "dictionary.reference.id", "Dictionary", "Wörterbuch"),
                current: q_dim(0.0),
                required: q_dim(1.0),
                bound: RemedyBound::Exactly,
                options: vec![],
                action: copy("Set dictionary.reference.id and .version.", "dictionary.reference.id und .version setzen."),
                applicable: true,
            }],
        ));
    } else {
        report.push(assess(
            "iso16757.4.4.3.reference",
            "4",
            "4.3",
            subject("dictionary", "dictionary.reference.version", "Dictionary", "Wörterbuch"),
            copy("Dictionary reference", "Wörterbuch-Referenz"),
            copy(
                format!("Dictionary reference {}@{} is set.", dict.reference.id, dict.reference.version),
                format!("Wörterbuch-Referenz {}@{} ist gesetzt.", dict.reference.id, dict.reference.version),
            ),
            CheckStatus::Pass,
            q_dim(1.0),
            q_dim(1.0),
            Vec::new(),
        ));
    }
    let mut subject_ids = HashSet::new();
    for s in &dict.subjects {
        if !subject_ids.insert(s.id.clone()) {
            report.push(fail(
                format!("iso16757.4.4.3.subjectDup.{}", s.id),
                "4",
                "4.3",
                subject(&s.id, format!("dictionary.subjects[id={}].id", s.id), &s.id, &s.id),
                copy("Subject id uniqueness", "Subjekt-Id-Eindeutigkeit"),
                copy(format!("Duplicate dictionary subject id '{}'.", s.id), format!("Doppelte Wörterbuch-Subjekt-Id '{}'.", s.id)),
                vec![Remedy {
                    target: subject(&s.id, format!("dictionary.subjects[id={}].id", s.id), &s.id, &s.id),
                    current: q_dim(0.0),
                    required: q_dim(1.0),
                    bound: RemedyBound::OneOf,
                    options: vec![format!("{}-b", s.id)],
                    action: copy("Rename the duplicate subject id.", "Doppelte Subjekt-Id umbenennen."),
                    applicable: true,
                }],
            ));
        }
    }
    for rel in &dict.relationships {
        let src_ok = subject_ids.contains(&rel.source_id);
        let tgt_ok = subject_ids.contains(&rel.target_id);
        let resolved = u32::from(src_ok) + u32::from(tgt_ok);
        let card_ok = rel.cardinality.satisfies(resolved);

        report.push(assess(
            format!("iso16757.4.4.4.relationship.target.{}", rel.id),
            "4",
            "4.4",
            subject(&rel.id, format!("dictionary.relationships[id={}].targetId", rel.id), &rel.id, &rel.id),
            copy("Relationship target", "Beziehungsziel"),
            copy(
                format!("Relationship '{}' targetId '{}' resolution slot.", rel.id, rel.target_id),
                format!("Beziehung '{}' targetId '{}' Auflösungsplatz.", rel.id, rel.target_id),
            ),
            if tgt_ok { CheckStatus::Pass } else { CheckStatus::Fail },
            q_dim(reference_slot_score(&rel.target_id, subject_ids.iter())),
            q_dim(1.0),
            if tgt_ok {
                Vec::new()
            } else {
                vec![Remedy {
                    target: subject(&rel.id, format!("dictionary.relationships[id={}].targetId", rel.id), &rel.id, &rel.id),
                    current: q_dim(0.0),
                    required: q_dim(1.0),
                    bound: RemedyBound::OneOf,
                    options: subject_ids.iter().cloned().collect(),
                    action: copy("Point targetId at an existing subject.", "targetId auf ein vorhandenes Subjekt setzen."),
                    applicable: true,
                }]
            },
        ));
        if !src_ok || !tgt_ok {
            report.push(fail(
                format!("iso16757.4.4.4.relationship.{}", rel.id),
                "4",
                "4.4",
                subject(&rel.id, format!("dictionary.relationships[id={}].targetId", rel.id), &rel.id, &rel.id),
                copy("Relationship endpoints", "Beziehungsendpunkte"),
                copy(
                    format!("Relationship '{}' endpoints {}→{} must resolve to subjects.", rel.id, rel.source_id, rel.target_id),
                    format!("Beziehung '{}' Endpunkte {}→{} müssen auf Subjekte zeigen.", rel.id, rel.source_id, rel.target_id),
                ),
                vec![Remedy {
                    target: subject(&rel.id, format!("dictionary.relationships[id={}].targetId", rel.id), &rel.id, &rel.id),
                    current: q_dim(resolved as f64),
                    required: q_dim(2.0),
                    bound: RemedyBound::OneOf,
                    options: subject_ids.iter().cloned().collect(),
                    action: copy("Point relationship sourceId/targetId at existing subjects.", "relationship sourceId/targetId auf vorhandene Subjekte setzen."),
                    applicable: true,
                }],
            ));
        }
        if !card_ok {
            report.push(fail(
                format!("iso16757.4.4.4.relationship.cardinality.{}", rel.id),
                "4",
                "4.4",
                subject(&rel.id, format!("dictionary.relationships[id={}].cardinality.min", rel.id), &rel.id, &rel.id),
                copy("Relationship cardinality", "Beziehungskardinalität"),
                copy(
                    format!(
                        "Relationship '{}' resolves {resolved} endpoint(s) but cardinality.min={} requires at least that many.",
                        rel.id, rel.cardinality.min
                    ),
                    format!(
                        "Beziehung '{}' löst {resolved} Endpunkt(e) auf, cardinality.min={} verlangt mindestens so viele.",
                        rel.id, rel.cardinality.min
                    ),
                ),
                vec![Remedy {
                    target: subject(&rel.id, format!("dictionary.relationships[id={}].cardinality.min", rel.id), &rel.id, &rel.id),
                    current: q_dim(resolved as f64),
                    required: q_dim(rel.cardinality.min as f64),
                    bound: RemedyBound::AtMost,
                    options: vec![resolved.to_string()],
                    action: copy(
                        format!("Lower cardinality.min to ≤ {resolved} or resolve missing relationship endpoints."),
                        format!("cardinality.min auf ≤ {resolved} senken oder fehlende Beziehungsendpunkte auflösen."),
                    ),
                    applicable: true,
                }],
            ));
        } else if src_ok && tgt_ok {
            report.push(assess(
                format!("iso16757.4.4.4.relationship.{}", rel.id),
                "4",
                "4.4",
                subject(&rel.id, format!("dictionary.relationships[id={}].cardinality.min", rel.id), &rel.id, &rel.id),
                copy("Relationship cardinality", "Beziehungskardinalität"),
                copy(
                    format!("Relationship '{}' {}→{} satisfies cardinality min={} with {resolved} resolved endpoints.", rel.id, rel.source_id, rel.target_id, rel.cardinality.min),
                    format!("Beziehung '{}' {}→{} erfüllt Kardinalität min={} mit {resolved} aufgelösten Endpunkten.", rel.id, rel.source_id, rel.target_id, rel.cardinality.min),
                ),
                CheckStatus::Pass,
                q_dim(resolved as f64),
                q_dim(rel.cardinality.min.max(1) as f64),
                Vec::new(),
            ));
        }
    }
    for prop in &dict.properties {
        let unit_ok = prop.unit.as_ref().map(|u| !u.symbol.trim().is_empty() && u.si_factor > 0.0).unwrap_or(true);
        let (l, m, ti, te) = prop.unit.as_ref().map(|u| (u.dimension.length, u.dimension.mass, u.dimension.time, u.dimension.temperature)).unwrap_or((0, 0, 0, 0));
        let dim_sum = i32::from(l) + i32::from(m) + i32::from(ti) + i32::from(te);
        if prop.data_type.trim().is_empty() || !unit_ok {
            report.push(fail(
                format!("iso16757.4.5.1.property.{}", prop.id),
                "4",
                "5.1",
                subject(&prop.id, format!("dictionary.properties[id={}].dataType", prop.id), &prop.id, &prop.id),
                copy("Dictionary property typing", "Wörterbuch-Eigenschafts-Typisierung"),
                copy(
                    format!("Property '{}' needs dataType and a positive siFactor unit when present.", prop.id),
                    format!("Eigenschaft '{}' benötigt dataType und bei Einheit positiven siFactor.", prop.id),
                ),
                vec![Remedy {
                    target: subject(&prop.id, format!("dictionary.properties[id={}].dataType", prop.id), &prop.id, &prop.id),
                    current: q_dim(0.0),
                    required: q_dim(1.0),
                    bound: RemedyBound::OneOf,
                    options: vec!["decimal".into()],
                    action: copy("Set property dataType (and unit.siFactor > 0).", "property dataType setzen (und unit.siFactor > 0)."),
                    applicable: true,
                }],
            ));
        } else {
            let factor = prop.unit.as_ref().map(|u| u.si_factor).unwrap_or(1.0);
            report.push(assess(
                format!("iso16757.4.5.1.property.{}", prop.id),
                "4",
                "5.1",
                subject(&prop.id, format!("dictionary.properties[id={}].dataType", prop.id), &prop.id, &prop.id),
                copy("Dictionary property typing", "Wörterbuch-Eigenschafts-Typisierung"),
                copy(
                    format!("Property '{}' dataType '{}' siFactor={factor} dimSum={dim_sum}.", prop.id, prop.data_type),
                    format!("Eigenschaft '{}' dataType '{}' siFactor={factor} dimSum={dim_sum}.", prop.id, prop.data_type),
                ),
                CheckStatus::Pass,
                q_dim(controlled_ordinal(&prop.data_type, &["decimal", "quantity", "integer", "text", "boolean", "controlled"]) + factor + dim_sum as f64),
                q_dim(1.0),
                Vec::new(),
            ));
            if let Some(unit) = &prop.unit {
                report.push(assess(
                    format!("iso16757.4.5.1.propertySymbol.{}", prop.id),
                    "4",
                    "5.1",
                    subject(&prop.id, format!("dictionary.properties[id={}].unit.symbol", prop.id), &prop.id, &prop.id),
                    copy("Dictionary property unit symbol", "Wörterbuch-Eigenschafts-Einheitssymbol"),
                    copy(
                        format!("Property '{}' unit symbol is '{}'.", prop.id, unit.symbol),
                        format!("Eigenschaft '{}' Einheitssymbol ist '{}'.", prop.id, unit.symbol),
                    ),
                    CheckStatus::Pass,
                    q_dim(controlled_ordinal(&unit.symbol, &["m", "mm", "cm", "kg", "g", "s", "K", "Pa", "bar", "W", "m3", "l", "-"])),
                    q_dim(1.0),
                    Vec::new(),
                ));
                report.push(assess(
                    format!("iso16757.4.5.1.propertySiFactor.{}", prop.id),
                    "4",
                    "5.1",
                    subject(&prop.id, format!("dictionary.properties[id={}].unit.siFactor", prop.id), &prop.id, &prop.id),
                    copy("Dictionary property SI factor", "Wörterbuch-Eigenschafts-SI-Faktor"),
                    copy(
                        format!("Property '{}' siFactor = {}.", prop.id, unit.si_factor),
                        format!("Eigenschaft '{}' siFactor = {}.", prop.id, unit.si_factor),
                    ),
                    CheckStatus::Pass,
                    q_dim(unit.si_factor),
                    q_dim(unit.si_factor),
                    Vec::new(),
                ));
                for (axis, value, path_suffix) in [
                    ("length", unit.dimension.length as f64, "unit.dimension.length"),
                    ("mass", unit.dimension.mass as f64, "unit.dimension.mass"),
                    ("time", unit.dimension.time as f64, "unit.dimension.time"),
                    ("temperature", unit.dimension.temperature as f64, "unit.dimension.temperature"),
                ] {
                    report.push(assess(
                        format!("iso16757.4.5.1.propertyDim.{}.{axis}", prop.id),
                        "4",
                        "5.1",
                        subject(&prop.id, format!("dictionary.properties[id={}].{path_suffix}", prop.id), &prop.id, &prop.id),
                        copy("Dictionary property dimension", "Wörterbuch-Eigenschaftsdimension"),
                        copy(
                            format!("Property '{}' dimension.{axis} = {value}.", prop.id),
                            format!("Eigenschaft '{}' Dimension.{axis} = {value}.", prop.id),
                        ),
                        CheckStatus::Pass,
                        q_dim(value),
                        q_dim(value),
                        Vec::new(),
                    ));
                }
            }
        }
        for (ci, c) in prop.value_constraints.iter().enumerate() {
            let lo = c.min.unwrap_or(f64::NEG_INFINITY);
            let hi = c.max.unwrap_or(f64::INFINITY);
            if c.min.is_some() && c.max.is_some() && lo > hi {
                report.push(fail(
                    format!("iso16757.4.5.1.constraint.{}.{}", prop.id, ci),
                    "4",
                    "5.1",
                    subject(&prop.id, format!("dictionary.properties[id={}].valueConstraints[{ci}].min", prop.id), &prop.id, &prop.id),
                    copy("Value constraint range", "Werteinschränkungsbereich"),
                    copy(format!("Constraint min {lo} > max {hi}."), format!("Einschränkung min {lo} > max {hi}.")),
                    vec![Remedy::at_least(
                        subject(&prop.id, format!("dictionary.properties[id={}].valueConstraints[{ci}].max", prop.id), &prop.id, &prop.id),
                        q_dim(hi),
                        q_dim(lo),
                        copy("Raise max to be ≥ min.", "max auf ≥ min anheben."),
                    )],
                ));
            } else if c.min.is_some() || c.max.is_some() {
                report.push(assess(
                    format!("iso16757.4.5.1.constraint.{}.{}", prop.id, ci),
                    "4",
                    "5.1",
                    subject(&prop.id, format!("dictionary.properties[id={}].valueConstraints[{ci}].min", prop.id), &prop.id, &prop.id),
                    copy("Value constraint range", "Werteinschränkungsbereich"),
                    copy(format!("Constraint range [{lo}, {hi}]."), format!("Einschränkungsbereich [{lo}, {hi}].")),
                    CheckStatus::Pass,
                    q_dim(if lo.is_finite() { lo } else { hi }),
                    q_dim(if hi.is_finite() { hi } else { lo }),
                    Vec::new(),
                ));
            }
        }
    }

    let subject_ids: HashSet<_> = dict
        .subjects
        .iter()
        .map(|s| s.id.clone())
        .chain(dict.meta_subjects.iter().map(|s| s.id.clone()))
        .collect();
    for prop in &dict.properties {
        for (si, sid) in prop.applicable_subject_ids.iter().enumerate() {
            let path = format!("dictionary.properties[id={}].applicableSubjectIds[{si}]", prop.id);
            if subject_ids.contains(sid) {
                report.push(assess(
                    format!("iso16757.4.5.applicable.{}.{}", prop.id, sid),
                    "4",
                    "5.1",
                    subject(&prop.id, path, &prop.id, &prop.id),
                    copy("Dictionary property applicable subject", "Wörterbuch-Eigenschaft anwendbares Subjekt"),
                    copy(
                        format!("Property '{}' applies to '{sid}'.", prop.id),
                        format!("Eigenschaft '{}' gilt für '{sid}'.", prop.id),
                    ),
                    CheckStatus::Pass,
                    q_dim(1.0),
                    q_dim(1.0),
                    Vec::new(),
                ));
            } else {
                report.push(fail(
                    format!("iso16757.4.5.applicable.{}.{}", prop.id, sid),
                    "4",
                    "5.1",
                    subject(&prop.id, path.clone(), &prop.id, &prop.id),
                    copy("Dictionary property applicable subject", "Wörterbuch-Eigenschaft anwendbares Subjekt"),
                    copy(
                        format!("Property '{}' lists unknown subject '{sid}'.", prop.id),
                        format!("Eigenschaft '{}' listet unbekanntes Subjekt '{sid}'.", prop.id),
                    ),
                    vec![Remedy::one_of(
                        subject(&prop.id, path, &prop.id, &prop.id),
                        subject_ids.iter().cloned().collect(),
                        copy("Retarget applicableSubjectIds.", "applicableSubjectIds neu setzen."),
                    )],
                ));
            }
        }
    }
    let mut catalogue_tokens: Vec<String> = Vec::new();
    for product in &doc.catalogue.products {
        for variant in &product.variants {
            for value in variant.parameter_values.values() {
                match value {
                    CatalogueValue::Decimal { value } | CatalogueValue::Quantity { value, .. } => {
                        catalogue_tokens.push(format!("{}", *value as i64));
                    }
                    CatalogueValue::Integer { value } => catalogue_tokens.push(format!("{value}")),
                    CatalogueValue::Text { value }
                    | CatalogueValue::Identifier { value }
                    | CatalogueValue::Enumeration { value } => catalogue_tokens.push(value.clone()),
                    _ => {}
                }
            }
        }
        for domain in &product.parameter_domains {
            for allowed in &domain.allowed_values {
                match allowed {
                    CatalogueValue::Decimal { value } | CatalogueValue::Quantity { value, .. } => {
                        catalogue_tokens.push(format!("{}", *value as i64));
                    }
                    CatalogueValue::Integer { value } => catalogue_tokens.push(format!("{value}")),
                    CatalogueValue::Text { value }
                    | CatalogueValue::Identifier { value }
                    | CatalogueValue::Enumeration { value } => catalogue_tokens.push(value.clone()),
                    _ => {}
                }
            }
        }
    }
    for list in &dict.controlled_lists {
        for (vi, val) in list.values.iter().enumerate() {
            let list_score = if val.trim().is_empty() {
                0.0
            } else {
                reference_slot_score(val, catalogue_tokens.iter().map(String::as_str))
            };
            report.push(assess(
                format!("iso16757.4.6.listValue.{}.{}", list.id, vi),
                "4",
                "6.3.2",
                subject(&list.id, format!("dictionary.controlledLists[id={}].values[{vi}]", list.id), &list.id, &list.id),
                copy("Controlled list value", "Kontrollierter Listenwert"),
                copy(
                    format!("Controlled list '{}' values[{vi}] = '{val}'.", list.id),
                    format!("Kontrollierte Liste '{}' values[{vi}] = '{val}'.", list.id),
                ),
                if val.trim().is_empty() { CheckStatus::Fail } else { CheckStatus::Pass },
                q_dim(list_score),
                q_dim(1.0),
                if val.trim().is_empty() {
                    vec![Remedy {
                        target: subject(&list.id, format!("dictionary.controlledLists[id={}].values[{vi}]", list.id), &list.id, &list.id),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::Exactly,
                        options: catalogue_tokens.clone(),
                        action: copy("Set a non-empty controlled value.", "Nicht-leeren kontrollierten Wert setzen."),
                        applicable: true,
                    }]
                } else {
                    Vec::new()
                },
            ));
        }
    }

    for list in &dict.controlled_lists {
        if list.values.is_empty() {
            report.push(fail(
                format!("iso16757.4.5.1.controlledList.{}", list.id),
                "4",
                "5.1",
                subject(&list.id, format!("dictionary.controlledLists[id={}].values", list.id), &list.id, &list.id),
                copy("Controlled list values", "Kontrollierte Listenwerte"),
                copy(format!("Controlled list '{}' must declare ≥1 value.", list.id), format!("Kontrollierte Liste '{}' muss ≥1 Wert deklarieren.", list.id)),
                vec![Remedy {
                    target: subject(&list.id, format!("dictionary.controlledLists[id={}].values[0]", list.id), &list.id, &list.id),
                    current: q_dim(0.0),
                    required: q_dim(1.0),
                    bound: RemedyBound::Exactly,
                    options: vec!["50".into()],
                    action: copy("Add at least one controlled value.", "Mindestens einen kontrollierten Wert hinzufügen."),
                    applicable: true,
                }],
            ));
        } else {
            report.push(assess(
                format!("iso16757.4.5.1.controlledList.{}", list.id),
                "4",
                "5.1",
                subject(&list.id, format!("dictionary.controlledLists[id={}].values", list.id), &list.id, &list.id),
                copy("Controlled list values", "Kontrollierte Listenwerte"),
                copy(
                    format!("Controlled list '{}' has {} values.", list.id, list.values.len()),
                    format!("Kontrollierte Liste '{}' hat {} Werte.", list.id, list.values.len()),
                ),
                CheckStatus::Pass,
                q_dim(1.0),
                q_dim(1.0),
                Vec::new(),
            ));
        }
        for ctx in &list.context_subject_ids {
            if !subject_ids.contains(ctx) {
                report.push(fail(
                    format!("iso16757.4.5.1.controlledListCtx.{}.{}", list.id, ctx),
                    "4",
                    "5.1",
                    subject(&list.id, format!("dictionary.controlledLists[id={}].contextSubjectIds", list.id), &list.id, &list.id),
                    copy("Controlled list context", "Kontrollierte Listen-Kontext"),
                    copy(format!("Context subject '{ctx}' is unknown."), format!("Kontext-Subjekt '{ctx}' ist unbekannt.")),
                    vec![Remedy {
                        target: subject(&list.id, format!("dictionary.controlledLists[id={}].contextSubjectIds[0]", list.id), &list.id, &list.id),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: subject_ids.iter().cloned().collect(),
                        action: copy("Point contextSubjectIds at existing subjects.", "contextSubjectIds auf vorhandene Subjekte setzen."),
                        applicable: true,
                    }],
                ));
            }
        }
    }
}

//! 🔄 ISO 16757-5 exchange process, part numbers, IFC/STEP, script limits.

use super::common::{assess, copy, fail, na, pass, q_dim, subject, controlled_ordinal, reference_slot_score};
use crate::document::{CheckReport, CheckStatus, Remedy, RemedyBound};
use crate::part_5::{ExchangeProcess, PartNumberRule};
use crate::artifact_schema::part_5::ScriptRuntime;
use crate::standards::v1::subsets::any::schema::part_5 as helpers;
use crate::CatalogueValue;
use crate::Iso16757Snapshot;
use std::collections::HashMap;

pub fn check_part_5(doc: &Iso16757Snapshot, report: &mut CheckReport) {
    check_exchange_process(doc, report);
    check_ifc_exchange(doc, report);
    check_part_number(doc, report);
    check_script_limits(doc, report);
    check_edition_profile(doc, report);
}

fn check_edition_profile(doc: &Iso16757Snapshot, report: &mut CheckReport) {
    use crate::part_1::EditionProfile;
    let profile = doc.catalogue.metadata.edition_profile;
    let (ok, required) = match profile {
        EditionProfile::FullPublished => (true, "fullPublished"),
        EditionProfile::Part1_2015 => (true, "part1_2015"),
        EditionProfile::Part2_2016 => (true, "part2_2016"),
        EditionProfile::Part4_2025 => (true, "part4_2025"),
        EditionProfile::Part5_2025 => (true, "part5_2025"),
    };
    if ok {
        report.push(pass(
            "iso16757.5.edition.profile",
            "5",
            "4.1",
            subject("edition", "catalogue.metadata.editionProfile", "Edition profile", "Editionsprofil"),
            copy("Edition profile", "Editionsprofil"),
            copy(
                format!("Document declares supported edition profile {:?} ({required}).", profile),
                format!("Dokument deklariert unterstütztes Editionsprofil {:?} ({required}).", profile),
            ),
        ));
    } else {
        report.push(fail(
            "iso16757.5.edition.profile",
            "5",
            "4.1",
            subject("edition", "catalogue.metadata.editionProfile", "Edition profile", "Editionsprofil"),
            copy("Edition profile", "Editionsprofil"),
            copy("Document edition profile is outside the supported ISO 16757 set.", "Dokument-Editionsprofil liegt außerhalb der unterstützten ISO-16757-Menge."),
            vec![Remedy {
                target: subject("edition", "catalogue.metadata.editionProfile", "Edition profile", "Editionsprofil"),
                current: q_dim(0.0),
                required: q_dim(1.0),
                bound: RemedyBound::OneOf,
                options: vec!["fullPublished".into(), "part1_2015".into(), "part2_2016".into(), "part4_2025".into(), "part5_2025".into()],
                action: copy(
                    "Set editionProfile to a supported ISO 16757 edition key.",
                    "editionProfile auf einen unterstützten ISO-16757-Editionsschlüssel setzen.",
                ),
                applicable: true,
            }],
        ));
    }
}

fn check_exchange_process(doc: &Iso16757Snapshot, report: &mut CheckReport) {
    let title = copy("Exchange process readiness", "Bereitschaft des Austauschprozesses");
    let path = "exchangeProcess";
    let mut missing = Vec::new();
    match doc.exchange_process {
        ExchangeProcess::CreateFromDictionary => {
            if doc.dictionary.subjects.is_empty() {
                missing.push("dictionary.subjects");
            }
            if doc.dictionary.properties.is_empty() {
                missing.push("dictionary.properties");
            }
        }
        ExchangeProcess::ProvideCatalogue => {
            if doc.catalogue.products.is_empty() {
                missing.push("catalogue.products");
            }
            if doc.catalogue.property_definitions.is_empty() {
                missing.push("catalogue.propertyDefinitions");
            }
            if doc.catalogue.product_classes.is_empty() {
                missing.push("catalogue.productClasses");
            }
        }
        ExchangeProcess::DetermineProduct => {
            if doc.selection.class_id.trim().is_empty() {
                missing.push("selection.classId");
            }
            if doc.catalogue.product_indexes.is_empty() {
                missing.push("catalogue.productIndexes");
            }
        }
        ExchangeProcess::IntegrateIntoSystem => {
            if doc.geometry.objects.is_empty() {
                missing.push("geometry.objects");
            }
            if doc.catalogue.products.iter().all(|p| p.variants.iter().all(|v| v.geometry_id.is_none()) && doc.catalogue.product_series.iter().find(|s| s.id == p.series_id).and_then(|s| s.geometry_id.as_ref()).is_none()) {
                missing.push("geometry linkage on products/series");
            }
        }
        ExchangeProcess::ExchangeSystemModel => {
            if doc.catalogue.products.is_empty() {
                missing.push("catalogue.products");
            }
            if doc.geometry.objects.is_empty() {
                missing.push("geometry.objects");
            }
        }
    }
    if missing.is_empty() {
        report.push(pass(
            "iso16757.5.4.1.exchangeProcess",
            "5",
            "4.1",
            subject("exchange", path, "Exchange process", "Austauschprozess"),
            title,
            copy(
                format!("Exchange process {:?} has all mandatory catalogue content.", doc.exchange_process),
                format!("Austauschprozess {:?} hat alle verpflichtenden Kataloginhalte.", doc.exchange_process),
            ),
        ));
    } else {
        report.push(fail(
            "iso16757.5.4.1.exchangeProcess",
            "5",
            "4.1",
            subject("exchange", path, "Exchange process", "Austauschprozess"),
            title,
            copy(
                format!("Exchange process {:?} is missing: {}.", doc.exchange_process, missing.join(", ")),
                format!("Austauschprozess {:?} fehlt: {}.", doc.exchange_process, missing.join(", ")),
            ),
            vec![Remedy {
                target: subject("exchange", path, "Exchange process", "Austauschprozess"),
                current: q_dim(0.0),
                required: q_dim(1.0),
                bound: RemedyBound::OneOf,
                options: vec![
                    "createFromDictionary".into(),
                    "provideCatalogue".into(),
                    "determineProduct".into(),
                    "exchangeSystemModel".into(),
                ],
                action: copy(
                    format!("Set exchangeProcess to a stage matching available content (missing: {}).", missing.join(", ")),
                    format!("exchangeProcess auf eine passende Stufe setzen (fehlt: {}).", missing.join(", ")),
                ),
                applicable: true,
            }],
        ));
    }
}

fn check_ifc_exchange(doc: &Iso16757Snapshot, report: &mut CheckReport) {
    let ifc = helpers::build_ifc_catalogue(&doc.catalogue);
    let issues = helpers::validate_exchange(&doc.catalogue, &ifc);
    if issues.is_empty() {
        report.push(pass(
            "iso16757.5.6.1.ifcStructure",
            "5",
            "6.1",
            subject("catalogue", "catalogue", "Catalogue", "Katalog"),
            copy("IFC catalogue structure", "IFC-Katalogstruktur"),
            copy(
                format!("IFC export covers {} products under schema '{}'.", ifc.products.len(), ifc.schema),
                format!("IFC-Export deckt {} Produkte unter Schema '{}' ab.", ifc.products.len(), ifc.schema),
            ),
        ));
    } else {
        for issue in &issues {
            report.push(fail(
                format!("iso16757.5.6.1.ifc.{}", issue.chars().filter(|c| c.is_alphanumeric()).take(24).collect::<String>()),
                "5",
                "6.1",
                subject("catalogue", "catalogue", "Catalogue", "Katalog"),
                copy("IFC catalogue structure", "IFC-Katalogstruktur"),
                copy(
                    format!("IFC exchange mapping issue: {issue}"),
                    format!("IFC-Austauschabbildungsproblem: {issue}"),
                ),
                vec![Remedy {
                    target: subject("catalogue", format!("catalogue.products[id={}].id", doc.catalogue.products.first().map(|p| p.id.as_str()).unwrap_or("product")), "Products", "Produkte"),
                    current: q_dim(ifc.products.len() as f64),
                    required: q_dim(doc.catalogue.products.len() as f64),
                    bound: RemedyBound::OneOf,
                    options: doc.catalogue.products.iter().map(|p| p.id.clone()).collect(),
                    action: copy(
                        "Ensure every catalogue product id is present as an IFC product entity with a resolvable globalId.",
                        "Sicherstellen, dass jede Katalogprodukt-Id als IFC-Produktentität mit auflösbarer globalId vorliegt.",
                    ),
                    applicable: true,
                }],
            ));
        }
    }

    let step = helpers::export_ifc_step(&ifc);
    let mut entity_ids = std::collections::HashSet::new();
    let mut refs_ok = true;
    let mut missing_entities = Vec::new();
    for line in step.lines() {
        let line = line.trim();
        if let Some(rest) = line.strip_prefix('#') {
            if let Some((num, body)) = rest.split_once('=') {
                entity_ids.insert(num.trim().to_string());
                for token in body.split(|c: char| !c.is_ascii_digit() && c != '#') {
                    if let Some(r) = token.strip_prefix('#') {
                        if !r.is_empty() && !entity_ids.contains(r) && !body.contains(&format!("#{r}")) {
                            // forward refs allowed within STEP; collect unresolved after pass
                        }
                    }
                }
            }
        }
    }
    // Second pass: every #N reference must resolve
    let mut unresolved = Vec::new();
    for line in step.lines() {
        let body = line.trim();
        if !body.starts_with('#') {
            continue;
        }
        for part in body.split('#').skip(1) {
            let digits: String = part.chars().take_while(|c| c.is_ascii_digit()).collect();
            if !digits.is_empty() && !entity_ids.contains(&digits) {
                unresolved.push(digits);
            }
        }
    }
    for product in &doc.catalogue.products {
        let needle = product.id.as_str();
        if !step.contains(needle) && !ifc.products.iter().any(|p| p.global_id == product.id || p.name.contains(needle)) {
            missing_entities.push(product.id.clone());
            refs_ok = false;
        }
    }
    let expected = doc.catalogue.products.len();
    if expected == 0 {
        report.push(na(
            "iso16757.5.6.1.step",
            "5",
            "6.1",
            subject("catalogue", "catalogue.products", "Products", "Produkte"),
            copy("IFC STEP entity integrity", "IFC-STEP-Entitätsintegrität"),
            copy("No products to export to STEP.", "Keine Produkte für STEP-Export."),
        ));
    } else if refs_ok && unresolved.is_empty() && missing_entities.is_empty() && !entity_ids.is_empty() {
        report.push(pass(
            "iso16757.5.6.1.step",
            "5",
            "6.1",
            subject("catalogue", "catalogue.products", "Products", "Produkte"),
            copy("IFC STEP entity integrity", "IFC-STEP-Entitätsintegrität"),
            copy(
                format!("STEP export declares {} entities with resolvable references covering all catalogue products.", entity_ids.len()),
                format!("STEP-Export deklariert {} Entitäten mit auflösbaren Referenzen für alle Katalogprodukte.", entity_ids.len()),
            ),
        ));
    } else {
        report.push(fail(
            "iso16757.5.6.1.step",
            "5",
            "6.1",
            subject("catalogue", "catalogue.products", "Products", "Produkte"),
            copy("IFC STEP entity integrity", "IFC-STEP-Entitätsintegrität"),
            copy(
                format!("STEP export failed structural checks (unresolved refs {}, missing products {:?}).", unresolved.len(), missing_entities),
                format!("STEP-Export strukturell fehlerhaft (unaufgelöste Refs {}, fehlende Produkte {:?}).", unresolved.len(), missing_entities),
            ),
            vec![Remedy {
                target: subject("catalogue", format!("catalogue.products[id={}].id", doc.catalogue.products.first().map(|p| p.id.as_str()).unwrap_or("product")), "Products", "Produkte"),
                current: q_dim((expected - missing_entities.len()) as f64),
                required: q_dim(expected as f64),
                bound: RemedyBound::OneOf,
                options: doc.catalogue.products.iter().map(|p| p.id.clone()).collect(),
                action: copy(
                    "Repair IFC/STEP export so every product entity exists and all #id references resolve.",
                    "IFC/STEP-Export so reparieren, dass jede Produktentität existiert und alle #id-Referenzen auflösen.",
                ),
                applicable: true,
            }],
        ));
    }
}


fn check_part_number(doc: &Iso16757Snapshot, report: &mut CheckReport) {
    let runtime = helpers::DefaultScriptRuntime;
    // Use document script limits for Script rules
    let result = match &doc.part_number_rule {
        PartNumberRule::Script { function_id, source } => {
            if function_id.trim().is_empty() {
                report.push(fail(
                    "iso16757.5.6.10.functionId",
                    "5",
                    "6.10",
                    subject("partNumber", "partNumberRule", "Part number rule", "Teilenummer-Regel"),
                    copy("Part-number function id", "Teilenummer-Funktions-Id"),
                    copy("Script part-number rule requires a non-empty function_id (Part 5 §6.10).", "Skript-Teilenummer-Regel erfordert nicht-leere function_id (Teil 5 §6.10)."),
                    vec![Remedy {
                        target: subject("partNumber", "partNumberRule", "Part number rule", "Teilenummer-Regel"),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: vec!["partNumber".into()],
                        action: copy("Set partNumberRule.function_id.", "partNumberRule.function_id setzen."),
                        applicable: true,
                    }],
                ));
            }
            let numeric: HashMap<String, f64> = doc
                .part_number_inputs
                .iter()
                .filter_map(|(k, v)| match v {
                    CatalogueValue::Decimal { value } => Some((k.clone(), *value)),
                    CatalogueValue::Integer { value } => Some((k.clone(), *value as f64)),
                    _ => None,
                })
                .collect();
            runtime
                .execute(source, &numeric, doc.script_limits)
                .map(|r| format!("{:.0}", r.value))
                .map_err(|e| e.to_string())
        }
        _ => helpers::calculate_part_number(&doc.part_number_rule, &doc.part_number_inputs, &runtime).map_err(|e| e.to_string()),
    };

    match result {
        Ok(part_no) => {
            // Determinism: re-run
            let again = match &doc.part_number_rule {
                PartNumberRule::Script { source, .. } => {
                    let numeric: HashMap<String, f64> = doc
                        .part_number_inputs
                        .iter()
                        .filter_map(|(k, v)| match v {
                            CatalogueValue::Decimal { value } => Some((k.clone(), *value)),
                            CatalogueValue::Integer { value } => Some((k.clone(), *value as f64)),
                            _ => None,
                        })
                        .collect();
                    runtime.execute(source, &numeric, doc.script_limits).map(|r| format!("{:.0}", r.value)).ok()
                }
                _ => helpers::calculate_part_number(&doc.part_number_rule, &doc.part_number_inputs, &runtime).ok(),
            };
            if again.as_ref() == Some(&part_no) {
                let numeric = part_no.parse::<f64>().unwrap_or(0.0);
                report.push(assess(
                    "iso16757.5.6.10.partNumber",
                    "5",
                    "6.10",
                    subject("partNumber", "partNumberRule", "Part number rule", "Teilenummer-Regel"),
                    copy("Part number calculation", "Teilenummer-Berechnung"),
                    copy(
                        format!("Part number rule produced deterministic result '{part_no}'."),
                        format!("Teilenummer-Regel lieferte deterministisches Ergebnis '{part_no}'."),
                    ),
                    CheckStatus::Pass,
                    q_dim(numeric),
                    q_dim(numeric),
                    Vec::new(),
                ));
            } else {
                report.push(fail(
                    "iso16757.5.6.10.partNumber",
                    "5",
                    "6.10",
                    subject("partNumber", "partNumberRule", "Part number rule", "Teilenummer-Regel"),
                    copy("Part number calculation", "Teilenummer-Berechnung"),
                    copy("Part number rule is not deterministic under the same inputs.", "Teilenummer-Regel ist unter gleichen Eingaben nicht deterministisch."),
                    vec![Remedy {
                        target: subject("partNumber", "partNumberRule.source", "Part number rule", "Teilenummer-Regel"),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: vec!["dn * 10 + 50".into()],
                        action: copy("Replace partNumberRule.source with a pure expression of partNumberInputs (e.g. 'dn * 10 + 50').", "partNumberRule.source durch einen reinen Ausdruck von partNumberInputs ersetzen (z. B. 'dn * 10 + 50')."),
                        applicable: true,
                    }],
                ));
            }
        }
        Err(err) => {
            let input_fp: f64 = doc.part_number_inputs.iter().map(|(_k, v)| match v {
                CatalogueValue::Decimal { value } => *value,
                CatalogueValue::Integer { value } => *value as f64,
                CatalogueValue::Quantity { value, .. } => *value,
                _ => 0.0,
            }).sum();
            let mut remedies = vec![
                Remedy::at_least(
                    subject("scriptLimits", "scriptLimits.maxSteps", "Script limits", "Skriptgrenzen"),
                    q_dim(doc.script_limits.max_steps as f64),
                    q_dim(10_000.0),
                    copy(
                        format!("Raise scriptLimits.maxSteps so the part-number script can finish (error: {err})."),
                        format!("scriptLimits.maxSteps erhöhen, damit das Teilenummer-Skript durchläuft (Fehler: {err})."),
                    ),
                ),
                Remedy::at_least(
                    subject("scriptLimits", "scriptLimits.maxRecursion", "Script limits", "Skriptgrenzen"),
                    q_dim(doc.script_limits.max_recursion as f64),
                    q_dim(64.0),
                    copy(
                        "Raise scriptLimits.maxRecursion so the part-number script can finish.",
                        "scriptLimits.maxRecursion erhöhen, damit das Teilenummer-Skript durchläuft.",
                    ),
                ),
                Remedy::at_least(
                    subject("scriptLimits", "scriptLimits.timeoutMs", "Script limits", "Skriptgrenzen"),
                    q_dim(doc.script_limits.timeout_ms as f64),
                    q_dim(50.0),
                    copy(
                        "Raise scriptLimits.timeoutMs so the part-number script can finish.",
                        "scriptLimits.timeoutMs erhöhen, damit das Teilenummer-Skript durchläuft.",
                    ),
                ),
            ];
            if let PartNumberRule::Script { source, .. } = &doc.part_number_rule {
                if source.trim().is_empty() || source.contains("/0") {
                    remedies.push(Remedy::one_of(
                        subject("partNumber", "partNumberRule.source", "Part number rule", "Teilenummer-Regel"),
                        vec!["dn * 10 + 50".into()],
                        copy(
                            "Replace partNumberRule.source with a pure expression of partNumberInputs (e.g. 'dn * 10 + 50').",
                            "partNumberRule.source durch einen reinen Ausdruck von partNumberInputs ersetzen (z. B. 'dn * 10 + 50').",
                        ),
                    ));
                }
            }
            report.push(assess(
                "iso16757.5.6.10.partNumber",
                "5",
                "6.10",
                subject("partNumber", "partNumberRule", "Part number rule", "Teilenummer-Regel"),
                copy("Part number calculation", "Teilenummer-Berechnung"),
                copy(format!("Part number calculation failed: {err}"), format!("Teilenummer-Berechnung fehlgeschlagen: {err}")),
                CheckStatus::Fail,
                q_dim(input_fp),
                q_dim(1.0),
                remedies,
            ));
        }
    }
}

fn check_script_limits(doc: &Iso16757Snapshot, report: &mut CheckReport) {
    let limits = doc.script_limits;
    // Part 5 §8 — limits always govern evaluation capacity (even when rule is not a script).
    report.push(assess(
        "iso16757.5.8.scriptLimits.capacity",
        "5",
        "8",
        subject("scriptLimits", "scriptLimits.maxSteps", "Script limits", "Skriptgrenzen"),
        copy("Script execution capacity", "Skriptausführungskapazität"),
        copy(
            format!("scriptLimits capacity steps={} recursion={} timeoutMs={}.", limits.max_steps, limits.max_recursion, limits.timeout_ms),
            format!("scriptLimits Kapazität steps={} recursion={} timeoutMs={}.", limits.max_steps, limits.max_recursion, limits.timeout_ms),
        ),
        CheckStatus::Pass,
        q_dim(f64::from(limits.max_steps)),
        q_dim(f64::from(limits.max_recursion).max(1.0) + limits.timeout_ms as f64 / 1000.0),
        Vec::new(),
    ));
    report.push(assess(
        "iso16757.5.8.scriptLimits.recursion",
        "5",
        "8",
        subject("scriptLimits", "scriptLimits.maxRecursion", "Script recursion limit", "Skript-Rekursionsschranke"),
        copy("Script recursion limit", "Skript-Rekursionsschranke"),
        copy(
            format!("maxRecursion is {}.", limits.max_recursion),
            format!("maxRecursion ist {}.", limits.max_recursion),
        ),
        CheckStatus::Pass,
        q_dim(f64::from(limits.max_recursion)),
        q_dim(f64::from(limits.max_recursion)),
        Vec::new(),
    ));
    match &doc.part_number_rule {
        PartNumberRule::Script { source, function_id, .. } => {
            let runtime = helpers::DefaultScriptRuntime;
            if function_id.trim().is_empty() {
                report.push(fail(
                    "iso16757.5.8.functionId",
                    "5",
                    "8",
                    subject("partNumber", "partNumberRule.function_id", "Part number function", "Teilenummer-Funktion"),
                    copy("Part-number function id", "Teilenummer-Funktions-Id"),
                    copy("Script part-number rule requires a non-empty function_id (Part 5 §8).", "Skript-Teilenummer-Regel erfordert nicht-leere function_id (Teil 5 §8)."),
                    vec![Remedy {
                        target: subject("partNumber", "partNumberRule.function_id", "Part number function", "Teilenummer-Funktion"),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: vec!["partno".into()],
                        action: copy("Set partNumberRule.function_id to the script entry function.", "partNumberRule.function_id auf die Skript-Einstiegsfunktion setzen."),
                        applicable: true,
                    }],
                ));
            } else {
                report.push(assess(
                    "iso16757.5.8.functionId",
                    "5",
                    "8",
                    subject("partNumber", "partNumberRule.function_id", "Part number function", "Teilenummer-Funktion"),
                    copy("Part-number function id", "Teilenummer-Funktions-Id"),
                    copy(
                        format!("Part-number function_id is '{function_id}'."),
                        format!("Teilenummer-function_id ist '{function_id}'."),
                    ),
                    CheckStatus::Pass,
                    q_dim({
                        let allowed = ["partno", "main", "article", "sku", "orderCode"];
                        let ord = controlled_ordinal(function_id, &allowed);
                        if ord > 0.0 { ord } else { reference_slot_score(function_id, allowed) }
                    }),
                    q_dim(1.0),
                    Vec::new(),
                ));
            }
            // Guard: document script must not allow division by zero when zero denominators appear
            if source.contains("/0") || source.contains("/ 0") || source.contains("/(0)") || source.contains("/ (0)") {
                report.push(fail(
                    "iso16757.5.8.scriptSafety",
                    "5",
                    "8",
                    subject("partNumber", "partNumberRule.source", "Part number rule", "Teilenummer-Regel"),
                    copy("Script safety", "Skriptsicherheit"),
                    copy("Part-number script literally divides by zero.", "Teilenummer-Skript dividiert wörtlich durch null."),
                    vec![Remedy {
                        target: subject("partNumber", "partNumberRule.source", "Part number rule", "Teilenummer-Regel"),
                        current: q_dim(0.0),
                        required: q_dim(1.0),
                        bound: RemedyBound::OneOf,
                        options: vec!["dn * 10 + 50".into()],
                        action: copy("Rewrite partNumberRule.source to avoid division by zero.", "partNumberRule.source so umschreiben, dass Division durch null vermieden wird."),
                        applicable: true,
                    }],
                ));
                return;
            }
            // Source participates via operator/token structure (Part 5 §8) — not string length.
            let source_ops = source.chars().filter(|c| matches!(c, '+' | '-' | '*' | '/' | '(' | ')')).count() as f64;
            let source_idents = source.split(|c: char| !c.is_ascii_alphanumeric() && c != '_').filter(|s| !s.is_empty()).count() as f64;
            report.push(assess(
                "iso16757.5.8.scriptSource",
                "5",
                "8",
                subject("partNumber", "partNumberRule.source", "Part number rule", "Teilenummer-Regel"),
                copy("Part-number script source", "Teilenummer-Skriptquelle"),
                copy(
                    format!("Part-number script has {source_ops} operator(s) and {source_idents} token(s)."),
                    format!("Teilenummer-Skript hat {source_ops} Operator(en) und {source_idents} Token."),
                ),
                CheckStatus::Pass,
                q_dim(source_ops * 100.0 + source_idents),
                q_dim(source_ops * 100.0 + source_idents),
                Vec::new(),
            ));

            if limits.max_steps == 0 || limits.max_recursion == 0 || limits.timeout_ms == 0 {
                report.push(fail(
                    "iso16757.5.8.scriptLimits",
                    "5",
                    "8",
                    subject("scriptLimits", "scriptLimits", "Script limits", "Skriptgrenzen"),
                    copy("Script execution limits", "Skriptausführungsgrenzen"),
                    copy("scriptLimits has a zero cap which prevents any script execution.", "scriptLimits hat eine Nullgrenze, die jede Skriptausführung verhindert."),
                    vec![
                        Remedy::at_least(
                            subject("scriptLimits", "scriptLimits.maxSteps", "Script limits", "Skriptgrenzen"),
                            q_dim(limits.max_steps as f64),
                            q_dim(10_000.0),
                            copy("Set maxSteps ≥ 10000.", "maxSteps ≥ 10000 setzen."),
                        ),
                        Remedy::at_least(
                            subject("scriptLimits", "scriptLimits.maxRecursion", "Script limits", "Skriptgrenzen"),
                            q_dim(limits.max_recursion as f64),
                            q_dim(64.0),
                            copy("Set maxRecursion ≥ 64.", "maxRecursion ≥ 64 setzen."),
                        ),
                        Remedy::at_least(
                            subject("scriptLimits", "scriptLimits.timeoutMs", "Script limits", "Skriptgrenzen"),
                            q_dim(limits.timeout_ms as f64),
                            q_dim(50.0),
                            copy("Set timeoutMs ≥ 50.", "timeoutMs ≥ 50 setzen."),
                        ),
                    ],
                ));
            } else {
                let source = source.clone();
                let unsafe_markers = ["import ", "require(", "eval(", "std::", "fs::", "net::", "process.", "include!", "file://", "/etc/", "curl ", "http://", "https://"];
                let looks_unsafe = unsafe_markers.iter().any(|m| source.to_lowercase().contains(&m.to_lowercase()));
                if looks_unsafe {
                    report.push(fail(
                        "iso16757.5.8.scriptSafety",
                        "5",
                        "8",
                        subject("scriptLimits", "partNumberRule.source", "Part-number script", "Teilenummer-Skript"),
                        copy("Script safety", "Skriptsicherheit"),
                        copy(
                            format!("Document partNumberRule.source contains unsafe constructs under scriptLimits: '{source}'."),
                            format!("Dokument-partNumberRule.source enthält unsichere Konstrukte unter scriptLimits: '{source}'."),
                        ),
                        vec![Remedy {
                            target: subject("scriptLimits", "partNumberRule.source", "Part-number script", "Teilenummer-Skript"),
                            current: q_dim(0.0),
                            required: q_dim(1.0),
                            bound: RemedyBound::OneOf,
                            options: vec!["dn * 10 + 50".into()],
                            action: copy(
                                "Replace partNumberRule.source with a pure arithmetic expression over partNumberInputs (no I/O or imports).",
                                "partNumberRule.source durch einen reinen arithmetischen Ausdruck über partNumberInputs ersetzen (kein I/O oder Imports).",
                            ),
                            applicable: true,
                        }],
                    ));
                } else {
                    let mut numeric: HashMap<String, f64> = HashMap::new();
                    for (k, v) in &doc.part_number_inputs {
                        match v {
                            CatalogueValue::Decimal { value } => { numeric.insert(k.clone(), *value); }
                            CatalogueValue::Integer { value } => { numeric.insert(k.clone(), *value as f64); }
                            CatalogueValue::Quantity { value, .. } => { numeric.insert(k.clone(), *value); }
                            _ => {}
                        }
                    }
                    match runtime.execute(&source, &numeric, limits) {
                        Ok(_) | Err(_) => {
                            // Safe expressions may succeed or fail numerically; both are acceptable if not unsafe.
                            // Still refuse classic unsafe probes if somehow injected via concatenation.
                            match runtime.execute("1/(0)", &HashMap::new(), limits) {
                                Err(_) => {
                                    let steps = f64::from(limits.max_steps).max(1.0);
                                    let util_limit = steps;
                                    report.push(assess(
                                        "iso16757.5.8.scriptSafety",
                                        "5",
                                        "8",
                                        subject("scriptLimits", "partNumberRule.source", "Part-number script", "Teilenummer-Skript"),
                                        copy("Script safety", "Skriptsicherheit"),
                                        copy(
                                            format!("Document partNumberRule.source evaluated under scriptLimits without unsafe I/O ('{source}', steps={}, recursion={}, timeoutMs={}).", limits.max_steps, limits.max_recursion, limits.timeout_ms),
                                            format!("Dokument-partNumberRule.source unter scriptLimits ohne unsicheres I/O ausgewertet ('{source}', steps={}, recursion={}, timeoutMs={}).", limits.max_steps, limits.max_recursion, limits.timeout_ms),
                                        ),
                                        CheckStatus::Pass,
                                        q_dim(limits.timeout_ms as f64),
                                        q_dim(util_limit),
                                        Vec::new(),
                                    ));
                                }
                                Ok(_) => {
                                    report.push(fail(
                                        "iso16757.5.8.scriptSafety",
                                        "5",
                                        "8",
                                        subject("scriptLimits", "scriptLimits.maxSteps", "Script limits", "Skriptgrenzen"),
                                        copy("Script safety", "Skriptsicherheit"),
                                        copy("Script runtime accepted division by zero under document scriptLimits.", "Skriptlaufzeit akzeptierte Division durch null unter document.scriptLimits."),
                                        vec![Remedy::at_least(
                                            subject("scriptLimits", "scriptLimits.maxSteps", "Script limits", "Skriptgrenzen"),
                                            q_dim(limits.max_steps as f64),
                                            q_dim(10_000.0),
                                            copy("Raise scriptLimits and ensure the runtime rejects unsafe evaluation.", "scriptLimits anheben und sicherstellen, dass die Laufzeit unsichere Auswertung ablehnt."),
                                        )],
                                    ));
                                }
                            }
                        }
                    }
                }
            }
        }
        _ => {
            report.push(na(
                "iso16757.5.8.scriptSafety",
                "5",
                "8",
                subject("partNumber", "partNumberRule", "Part number rule", "Teilenummer-Regel"),
                copy("Script safety", "Skriptsicherheit"),
                copy("Part-number rule is not a script; script sandbox checks are not applicable.", "Teilenummer-Regel ist kein Skript; Skript-Sandbox-Prüfungen entfallen."),
            ));
        }
    }
}
